// Not official and not affiliated with the companies. Each claim carries basis (official|reported|general) and source indexes.
window.COMPANIES = [{"id":"masan","name":"Masan Consumer (Tập đoàn Masan)","program":"Masan Young Entrepreneur (MYE) – Sales Program","industry":"FMCG","lastChecked":"2026-11-13","summary":"Masan Young Entrepreneur (MYE) là chương trình quản trị viên tập sự của Masan Consumer; mùa 2026 là MYE – Sales Program (luân chuyển GT, MT, Shopper và hướng tới vị trí Sales/Shopper Marketing Supervisor), song song có MYE – Technology 2026. Quy trình 4 vòng, kết thúc bằng thuyết trình chuyên môn; đòi hỏi sẵn sàng làm việc ở tỉnh.","intake":{"text":"MYE – Sales Program 2026: nộp đơn 07/05–07/06/2026; Kiểm tra năng lực 06/2026; Phỏng vấn sơ bộ 07/2026; Thuyết trình chuyên môn 07/2026. MYE – Sales Program 2025 cũng đã được tuyển (đăng tin cuối năm 2025). Thời điểm đợt kế tiếp: chưa công bố.","basis":"official","src":[0,1,2,4]},"eligibility":[{"text":"Sinh viên mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm; GPA tích lũy từ 6.5/10 trở lên (MYE Sales 2026).","basis":"official","src":[0,1]},{"text":"Đam mê Kinh doanh & Bán hàng, đặc biệt FMCG; sẵn sàng làm việc tại các tỉnh thành được chỉ định.","basis":"official","src":[0,1]}],"functions":[{"text":"MYE – Sales Program 2026: Sales Supervisor – General Trade, Sales Supervisor – Modern Trade, Shopper Marketing Supervisor; luân chuyển qua GT, MT, Shopper.","basis":"official","src":[0]},{"text":"MYE – Technology 2026 cho mảng công nghệ.","basis":"official","src":[3]}],"stages":[{"name":"Vòng 1: Nộp đơn ứng tuyển","what":"Nộp đơn online (2026: 07/05–07/06). Theo chia sẻ cũ của ứng viên, hồ sơ MYE gồm CV, bảng điểm và application form.","tips":["Nêu trải nghiệm bán hàng, kinh doanh nhỏ hoặc dự án có số liệu doanh số.","Ghi rõ sẵn sàng làm việc tại tỉnh."],"basis":"official","src":[0,6]},{"name":"Vòng 2: Kiểm tra năng lực","what":"Bài kiểm tra năng lực (06/2026). Hình thức chính thức (online hay tại chỗ, số phần, thời gian): Chưa có thông tin công khai đáng tin cậy. Ứng viên các mùa trước kể có vòng 'test khả năng' sau vòng hồ sơ.","tips":["Luyện Quant và DI với số liệu bán hàng (doanh số, thị phần, tăng trưởng).","Luyện Logical có bấm giờ."],"basis":"official","src":[0,6]},{"name":"Vòng 3: Phỏng vấn sơ bộ","what":"Phỏng vấn sơ bộ (07/2026). Ứng viên các mùa trước kể có phỏng vấn với HR và phỏng vấn nhóm với case study.","tips":["Chuẩn bị câu chuyện STAR về nhiệt huyết, cầu tiến, kỷ luật.","Ra cửa hàng tạp hóa/siêu thị quan sát cách trưng bày sản phẩm Masan để có ví dụ thực tế."],"basis":"official","src":[0,6]},{"name":"Vòng 4: Thuyết trình chuyên môn","what":"Thuyết trình chuyên môn (07/2026). Nội dung chính thức chưa công bố; theo chia sẻ ứng viên mùa trước, vòng cuối có thể yêu cầu chuẩn bị khoảng 30 phút và trình bày 3 slide PowerPoint về một vấn đề của phòng ban ứng tuyển.","tips":["Luyện dựng 3 slide trong 30 phút: vấn đề – phân tích số liệu – đề xuất hành động.","Nắm các kênh GT/MT và khái niệm shopper marketing."],"basis":"official","src":[0,6]}],"tests":[{"name":"Kiểm tra năng lực","provider":null,"format":"Chưa có thông tin công khai đáng tin cậy về dạng câu hỏi và thời gian cho mùa 2026; Masan chỉ công bố tên vòng và tháng.","basis":"official","src":[0]}],"values":{"name":"Tố chất ứng viên MYE Sales 2026 (theo tin tuyển dụng)","items":["Nhiệt huyết","Cầu tiến","Kỷ luật","Tinh thần học hỏi cao","Đam mê Kinh doanh & Bán hàng (FMCG)"],"basis":"official","src":[1]},"prep":["Đọc Study guide phần DI và Quant, tập trung bài toán doanh số, % tăng trưởng, thị phần.","Mental math gym hằng ngày — tính nhanh là lợi thế khi phân tích số liệu bán hàng.","Làm 'Masan-style practice test' trong Mock test, sau đó luyện chủ đề SJT cho tình huống quản lý đội bán hàng.","Đi thực địa: quan sát 3–5 điểm bán (GT và MT), ghi lại cách trưng bày, giá, khuyến mãi các nhãn Masan.","Luyện thuyết trình 3 slide trong 30 phút với một đề case bán hàng.","Chuẩn bị câu trả lời thật lòng về việc làm ở tỉnh và lộ trình Sales Supervisor."],"mock":{"title":"Masan-style practice test","topics":{"Quant":5,"Logical":4,"Verbal":3,"DI":6,"SJT":2},"minutes":25,"navigation":true,"note":"Masan chưa công bố định dạng vòng Kiểm tra năng lực; cấu hình nghiêng về DI/Quant vì vị trí Sales cần phân tích số liệu, thêm SJT cho tình huống quản lý. Vòng thuyết trình chuyên môn không mô phỏng được trong app.","basis":"general","src":[0]},"pitfalls":["Không sẵn sàng làm việc ở tỉnh nhưng vẫn ứng tuyển — đây là điều kiện công bố (official).","Thuyết trình dàn trải, quá nhiều slide khi thời gian chuẩn bị ngắn (reported từ ứng viên mùa trước).","Dùng mô tả 5 vòng của các mùa MT cũ thay vì lịch 4 vòng mùa 2026 (general)."],"sources":[{"title":"MASAN YOUNG ENTREPRENEUR - SALES PROGRAM 2026","url":"https://masanconsumer.com.vn/","publisher":"Masan Consumer","year":"2026","accessed":"2026-11-13"},{"title":"[Toàn Quốc] Chương Trình Tuyển Dụng 'Masan Young Entrepreneur - Sales Program 2026'","url":"https://ybox.vn/tuyen-dung/toan-quoc-chuong-trinh-tuyen-dung-masan-young-entrepreneur-sales-program-2026-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-tai-tap-doan-hang-tieu-dung-nhanh-masan-69fe7ec073257002f74ee575","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Masan Young Entrepreneur - Sales Program 2026","url":"https://jobs.neu.edu.vn/jobs/masan-young-entrepreneur-sales-program-2026-masan-consumer-1202605111547","publisher":"Trung tâm Đổi mới sáng tạo và Hướng nghiệp - ĐH Kinh tế Quốc dân","year":"2026","accessed":"2026-11-13"},{"title":"Chương trình Masan Young Entrepreneur - Technology 2026 (MYE Tech 2026)","url":"https://www.fit.hcmus.edu.vn/tin-tuc/d/chuong-trinh-masan-young-entrepreneur-technology-2026-mye-tech-2026","publisher":"Khoa CNTT - ĐH Khoa học Tự nhiên TP.HCM","year":"2026","accessed":"2026-11-13"},{"title":"[HCM/Miền Trung/Miền Nam] Chương Trình Tuyển Dụng Quản Lý Kinh Doanh Tập Sự Masan Young Entrepreneur - Sales Program 2025","url":"https://ybox.vn/tuyen-dung/hcm-mien-trung-mien-nam-chuong-trinh-tuyen-dung-quan-ly-kinh-doanh-tap-su-masan-young-entrepreneur-sales-program-2025-tai-tap-doan-hang-tieu-dung-nhanh-masan-68f5d640aa72e20d8c60fe90","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"Làm Management Trainee tại Masan là trải nghiệm thế nào?","url":"https://blog.tomorrowmarketers.org/lam-management-trainee-tai-masan-la-trai-nghiem-the-nao-anh-xuan-vinh/","publisher":"Tomorrow Marketers","year":"n/a","accessed":"2026-11-13"},{"title":"Masan Consumer Tuyển Dụng: Kinh Nghiệm Thi Management Trainee & Các Vị Trí Hot","url":"https://viecoi.vn/cam-nang-nghe-nghiep/chi-tiet-chia-se-kinh-nghiem-ve-chuong-trinh-tuyen-dung-management-trainee-cua-masan-consumer-986.html","publisher":"Viecoi.vn","year":"n/a","accessed":"2026-11-13"}]},{"id":"pg","name":"P&G Vietnam","program":"P&G LEAD GEN (internship-to-Management Trainee route)","industry":"FMCG","lastChecked":"2026-11-13","summary":"Tại Việt Nam, đường vào vị trí quản lý cấp đầu của P&G chủ yếu là P&G LEAD GEN: chương trình thực tập toàn thời gian có lương 6 tháng cho sinh viên đại học, người làm tốt có thể được đề nghị vị trí quản lý toàn thời gian sau đánh giá hiệu suất. P&G tuyển theo hướng 'hire from within', nên điểm khác biệt là bài đánh giá online chuẩn hoá toàn cầu (PEAK Performance Assessment và, tuỳ vị trí, Interactive Assessment), sau đó nhiều vòng phỏng vấn với quản lý cấp cao. Chưa thấy tin tuyển 'Management Trainee' riêng của P&G Việt Nam trong giai đoạn gần đây.","intake":{"text":"LEAD GEN 2026: cổng nghề nghiệp VinUni ghi thời gian 29/10–12/11/2025, làm toàn thời gian từ tháng 1/2026 (official tin tuyển qua trường). LEAD GEN 2027: một kho dữ liệu cộng đồng sinh viên trên GitHub ghi hạn 31/10/2026, xét đơn theo thứ tự nộp, một số track đã đủ người từ giữa tháng 10 (reported). Nhìn chung đơn mở khoảng tháng 9–11, xét cuốn chiếu nên nộp sớm.","basis":"reported","src":[4,3,5]},"eligibility":[{"text":"Sinh viên đại học, hoặc đã học xong chương trình nhưng chưa nhận bằng.","basis":"official","src":[3,4]},{"text":"Làm việc toàn thời gian được trong 6 tháng (đợt 2026 bắt đầu từ tháng 1/2026); tiếng Anh tốt cả nói và viết; ưu tiên có kinh nghiệm thực tập.","basis":"official","src":[4,3]},{"text":"Trợ cấp được đăng là 12–17 triệu VND/tháng (tin LEAD GEN 2026 trên YBOX).","basis":"official","src":[3]}],"functions":[{"text":"Các track LEAD GEN được đăng gồm Sales, Brand, Finance, HR Analytics, Data & Automation (TP.HCM) và các vị trí kỹ thuật như Process Engineer Intern tại nhà máy Bình Dương.","basis":"official","src":[3,6,5]}],"stages":[{"name":"Online Application","what":"Nộp đơn trên pgcareers.com; theo tin LEAD GEN, đơn được xét theo thứ tự nộp trước sau.","tips":["Nộp sớm ngay khi mở đơn vì xét cuốn chiếu và track có thể đủ người.","CV tiếng Anh 1 trang, mỗi gạch đầu dòng có kết quả định lượng."],"basis":"official","src":[3,2]},{"name":"Online Assessment Tests (PEAK Performance Assessment + Interactive Assessment)","what":"Sau khi nộp đơn, ứng viên có thể được mời làm một hoặc nhiều bài đánh giá online đo những kỹ năng mà phỏng vấn khó thấy; kết quả gửi qua email trong vòng 30 ngày. PEAK đánh giá nền tảng, kinh nghiệm, sở thích và thái độ làm việc so với năng lực của P&G (khoảng 20 phút, lưu được các phần đã xong). Tuỳ vị trí, có thêm Interactive Assessment (khoảng 30 phút, chuỗi bài đánh giá năng lực nhận thức ngắn).","tips":["PEAK: trả lời trung thực và nhất quán; đọc PVP của P&G trước để hiểu hành vi P&G đề cao.","Interactive Assessment: luyện các dạng game nhận thức (suy luận, tính nhẩm, trí nhớ không gian) có bấm giờ.","Kiểm tra email (cả thư rác) để không lỡ link đánh giá."],"basis":"official","src":[0,1,2]},{"name":"Phone Interview","what":"Phỏng vấn qua điện thoại (theo tin LEAD GEN 2026).","tips":["Chuẩn bị câu trả lời ngắn gọn cho 'Why P&G / Why track này' và 2–3 câu chuyện STAR.","Nghe điện thoại ở nơi yên tĩnh, có sẵn CV trước mặt."],"basis":"official","src":[3]},{"name":"3 rounds of interview with C-levels","what":"Tin LEAD GEN 2026 ghi 3 vòng phỏng vấn với lãnh đạo cấp cao. Theo trang hiring process toàn cầu, phỏng vấn giúp P&G hiểu ứng viên và để ứng viên đặt câu hỏi; có thể có thêm bước tuỳ vị trí. Ứng viên và các trang luyện thi báo cáo phỏng vấn chủ yếu là câu hỏi hành vi về kinh nghiệm quá khứ.","tips":["Gắn mỗi câu chuyện STAR với một hành vi cụ thể: lãnh đạo, chủ động nhận trách nhiệm (ownership), sáng tạo, thực thi đến cùng.","Nêu rõ vai trò của bạn ('tôi' chứ không chỉ 'chúng tôi') và kết quả bằng số.","Chuẩn bị câu hỏi ngược sâu về ngành hàng/brand P&G ở Việt Nam."],"basis":"official","src":[3,2,9]}],"tests":[{"name":"PEAK Performance Assessment","provider":null,"format":"Theo P&G: đánh giá nền tảng, kinh nghiệm, sở thích và thái độ làm việc, đo mức phù hợp với năng lực P&G; đa số ứng viên mất khoảng 20 phút; link gửi qua email; thoát giữa chừng vẫn lưu các phần đã xong. Các trang luyện thi mô tả đây là bài trắc nghiệm tính cách kết hợp tình huống (SJT) (reported).","basis":"official","src":[1,0,8]},{"name":"Interactive Assessment (IA)","provider":"Aon (cut-e), theo các trang luyện thi, P&G không công bố","format":"Theo P&G: khoảng 30 phút, hơn 20 ngôn ngữ, gồm chuỗi bài đánh giá năng lực nhận thức ngắn, giao tuỳ vị trí. Các trang luyện thi mô tả 3 game Switch Challenge, Digit Challenge, Grid Challenge (suy luận suy diễn, số học, trí nhớ không gian), có giới hạn thời gian và không quay lại câu trước được (reported).","basis":"official","src":[0,8]}],"values":{"name":"P&G Purpose, Values and Principles (PVP)","items":["Integrity","Leadership","Ownership","Passion for Winning","Trust","Ghi chú: 'Success Drivers' / 'PEAK Performance Factors' chỉ xuất hiện trên các trang luyện thi, chưa có thông tin công khai đáng tin cậy từ P&G về danh sách chính thức."],"basis":"official","src":[7]},"prep":["Theo dõi pgcareers.com và kênh tuyển dụng của trường từ tháng 9, nộp LEAD GEN sớm vì xét theo thứ tự nộp.","Study guide: đọc phần PEAK (tính cách + tình huống) và Interactive Assessment (game nhận thức) để biết mỗi bài đo gì.","Mental math gym hằng ngày: game kiểu Digit Challenge cần tính nhẩm nhanh và chính xác.","Luyện chủ đề Logical (quy luật, suy luận suy diễn) có bấm giờ để chuẩn bị cho dạng Switch Challenge.","Luyện chủ đề SJT, đối chiếu lựa chọn với 5 giá trị PVP (Integrity, Leadership, Ownership, Passion for Winning, Trust).","Làm Mock test 'P&G-style' ở chế độ không quay lại câu trước, đúng giới hạn thời gian.","Viết 6–8 câu chuyện STAR bằng tiếng Anh cho phỏng vấn điện thoại và 3 vòng với C-level; tập nói kết quả bằng số."],"mock":{"title":"P&G-style practice test","topics":{"Quant":6,"Logical":6,"Verbal":0,"DI":2,"SJT":6},"minutes":20,"navigation":false,"note":"PEAK là bài tính cách và tình huống (khoảng 20 phút) nên dùng SJT để luyện tư duy theo PVP; Interactive Assessment là game nhận thức (tính nhẩm, suy luận, trí nhớ không gian) nên dùng Quant/Logical tốc độ cao. App không mô phỏng được giao diện game Aon (Switch/Digit/Grid) hay phần trí nhớ không gian. Tắt quay lại câu trước theo báo cáo của ứng viên về IA.","basis":"reported","src":[0,1,8]},"pitfalls":["Nộp muộn: LEAD GEN xét theo thứ tự nộp và một số track được báo đã đủ người trước hạn (reported).","Trả lời PEAK theo kiểu 'hình mẫu lý tưởng' thiếu nhất quán thay vì trung thực (general).","Ở game IA, cố chính xác tuyệt đối mà mất tốc độ, hoặc ngược lại; các trang luyện thi báo cáo không quay lại câu trước được (reported).","Câu chuyện STAR dùng 'chúng tôi' và không nêu kết quả đo được (general).","Bỏ sót email mời làm bài đánh giá, vì kết quả và link đều gửi qua email (official)."],"sources":[{"title":"Assessment Overview at P&G","url":"https://pgcareers.com/assessment-overviews","publisher":"P&G Careers","year":"2025","accessed":"2026-11-13"},{"title":"Peak Performance Assessment Overview","url":"https://www.pgcareers.com/eu/en/peak-performance-assessment","publisher":"P&G Careers","year":"2025","accessed":"2026-11-13"},{"title":"How do we hire?","url":"https://pgcareers.com/hiring-process","publisher":"P&G Careers","year":"2025","accessed":"2026-11-13"},{"title":"[Bình Dương-HCM] Chương trình tuyển dụng thực tập sinh P&G Lead Gen 2026","url":"https://ybox.vn/tuyen-dung/binh-duong-hcm-chuong-trinh-tuyen-dung-thuc-tap-sinh-p-and-g-lead-gen-2026-tu-tap-doan-hang-tieu-dung-da-quoc-gia-procter-and-gamble-muc-luong-12-17-trieu-thang-68ff7425c7b0e427d28e9b2c","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"P&G LEAD GEN 2026","url":"https://careerportal.vinuni.edu.vn/job/pg-lead-gen-2026-12217","publisher":"VinUni Career Portal","year":"2025","accessed":"2026-11-13"},{"title":"feat: P&G LEAD GEN 2027 internship (vn-student-programs)","url":"https://github.com/techjobs-vn/vn-student-programs/pull/30","publisher":"GitHub (cộng đồng)","year":"2026","accessed":"2026-11-13"},{"title":"P&G LEAD GEN Sales Intern Full-time 2026","url":"https://vn.joboko.com/viec-lam-hcm-tap-doan-hang-tieu-dung-da-quoc-gia-procter-gamble-p-g-tuyen-dung-p-g-lead-gen-sales-intern-full-time-2026-xvi6293798","publisher":"Joboko","year":"2025","accessed":"2026-11-13"},{"title":"Purpose, Values and Principles","url":"https://us.pg.com/policies-and-practices/purpose-values-and-principles/","publisher":"Procter & Gamble","year":"2025","accessed":"2026-11-13"},{"title":"P&G Online Assessment Test guide (third-party prep)","url":"https://www.jobtestprep.com/procter-and-gamble-assessment","publisher":"JobTestPrep","year":"2026","accessed":"2026-11-13"},{"title":"Procter & Gamble Interview Questions in Vietnam (candidate-reported)","url":"https://www.glassdoor.com/Interview/Procter-and-Gamble-Vietnam-Interview-Questions-EI_IE544.0,18_IL.19,26_IN251.htm","publisher":"Glassdoor","year":"n/a","accessed":"2026-11-13"}]},{"id":"unilever","name":"Unilever Vietnam","program":"Unilever Future Leaders Programme (UFLP)","industry":"FMCG","lastChecked":"2026-11-13","summary":"UFLP là chương trình Management Trainee (quản trị viên tập sự) thường niên của Unilever Việt Nam, dành cho sinh viên sắp/mới tốt nghiệp hoặc người có tối đa 2 năm kinh nghiệm, quốc tịch Việt Nam. Điểm khác biệt: Unilever toàn cầu dùng game đánh giá (profile assessment) và Digital Interview quay sẵn thay cho vòng phỏng vấn đầu, rồi kết thúc bằng Discovery Centre mô phỏng 'một ngày làm Future Leader'. Tin tuyển UFLP 2026 tại Việt Nam ghi 3 vòng: Online Application & Aptitude Test → Digital Interview → Discovery Center.","intake":{"text":"UFLP 2026: hạn nộp 23:59 ngày 29/12/2025; Digital Interview tháng 1–2/2026, Discovery Center tháng 3/2026, bắt đầu làm việc tháng 4/2026 (official). Chu kỳ trước: UFLP 2025 hạn 23:59 ngày 26/01/2025 (theo cổng việc làm NEU). UFLP 2027: một nhân viên Unilever đăng trên LinkedIn rằng đơn đã mở, hạn 23:59 ngày 30/11/2026 (reported, chưa đối chiếu được với trang chính thức). Nhìn chung đơn mở khoảng tháng 11 đến tháng 1.","basis":"official","src":[0,1,2,6,5]},"eligibility":[{"text":"UFLP 2026: sinh viên tốt nghiệp năm 2026 hoặc 2027 (Cử nhân/Thạc sĩ), hoặc tối đa 2 năm kinh nghiệm toàn thời gian; quốc tịch Việt Nam.","basis":"official","src":[1]},{"text":"UFLP 2026: GPA từ 7.0/10.0 hoặc tương đương; kinh nghiệm lãnh đạo ở CLB, tổ chức, dự án xã hội là điểm cộng.","basis":"official","src":[1]},{"text":"Chỉ đơn nộp qua link/cổng chính thức của Unilever mới hợp lệ; đơn nộp qua nền tảng khác không được xét.","basis":"official","src":[1]},{"text":"Yêu cầu tiếng Anh cụ thể (IELTS/TOEIC): Chưa có thông tin công khai đáng tin cậy. Tuy vậy các vòng Digital Interview và Discovery Centre của UFLP toàn cầu diễn ra bằng tiếng Anh nên cần tiếng Anh giao tiếp tốt.","basis":"general","src":[3]}],"functions":[{"text":"UFLP 2026 Việt Nam tuyển các mảng: Marketing, Customer Development (Sales), Supply Chain (bao gồm Manufacturing), Unilever Food Solutions, Finance, Human Resources.","basis":"official","src":[2,0,1]},{"text":"Ở UFLP toàn cầu, ứng viên chỉ được chọn một function trong một đơn ứng tuyển.","basis":"official","src":[3]}],"stages":[{"name":"Online Application & Aptitude Test (Vòng 1)","what":"Điền đơn trực tuyến trên cổng tuyển dụng Unilever và làm bài đánh giá năng lực trực tuyến. Ở UFLP toàn cầu (UK & Ireland 2026), phần đánh giá là 'profile assessment' gồm 5 game ngắn đo đặc điểm nhận thức, cảm xúc và xã hội, có phản hồi cá nhân sau khi chơi. Tin tuyển Việt Nam chỉ ghi 'Aptitude Test', không nêu số game hay nhà cung cấp.","tips":["Làm trong môi trường yên tĩnh, máy tính ổn định, một lần ngồi liền; game đo phản xạ và trí nhớ nên tránh mệt mỏi.","Chơi thật theo cách tự nhiên: game đo đặc điểm (traits) chứ không chỉ đúng/sai, cố 'đoán ý' thường phản tác dụng.","Luyện Mental math gym và chủ đề Logical (quy luật, chuỗi) để tăng tốc độ xử lý.","Chọn function kỹ trước khi nộp vì chỉ được chọn một."],"basis":"official","src":[1,3]},{"name":"Digital Interview (Vòng 2)","what":"Phỏng vấn video quay sẵn: trả lời các câu hỏi được cài sẵn trên nền tảng online, có thể làm bất cứ lúc nào trong hạn. Trang UFLP toàn cầu mô tả một số câu hỏi ngắn kèm một business case với một số stream, và nói bài nộp được người thật xem xét (Unilever nói không dùng AI làm công cụ sàng lọc ở bước này). Ứng viên báo cáo trên Glassdoor rằng mỗi câu có giới hạn thời gian và chỉ được quay một lần. UFLP 2026 Việt Nam: tháng 1–2/2026.","tips":["Chuẩn bị 5–6 câu chuyện theo STAR về lãnh đạo, vượt khó, làm việc nhóm, tạo tác động.","Tìm hiểu các brand của Unilever Việt Nam và tin tức công ty, vì TargetJobs nhận xét Unilever cố ý ít tiết lộ nội dung câu hỏi.","Tập trả lời trước camera có bấm giờ (khoảng 1–2 phút/câu), nhìn vào ống kính, nói tiếng Anh rõ ràng.","Với business case: nêu cấu trúc (vấn đề → phân tích → đề xuất → tác động) trong thời gian ngắn."],"basis":"official","src":[2,3,4,8]},{"name":"Discovery Center (Vòng 3)","what":"Vòng cuối kiểu assessment centre, được thiết kế để ứng viên trải nghiệm 'một ngày làm Future Leader' tại Unilever (theo trang UFLP toàn cầu). Ứng viên ở các thị trường khác báo cáo có bài tập nhóm, thuyết trình và bài tập cá nhân. Định dạng cụ thể tại Việt Nam (trực tiếp hay online, số bài tập): Chưa có thông tin công khai đáng tin cậy. UFLP 2026 Việt Nam: tháng 3/2026.","tips":["Luyện case nhóm: lắng nghe, xây trên ý người khác, giữ thời gian, tổng kết; vai trò không quan trọng bằng chất lượng đóng góp.","Luyện đọc nhanh số liệu kinh doanh (DI) để ra quyết định dựa trên dữ liệu khi thuyết trình.","Chuẩn bị câu trả lời 'Why Unilever / Why function này' gắn với purpose và brand cụ thể."],"basis":"official","src":[2,3]},{"name":"UFLP 2027 (thông tin đang chờ xác nhận)","what":"Bài đăng LinkedIn của một nhân viên Unilever về UFLP 2027 liệt kê 4 bước: CV application, psychometric assessments, group case interview, Discovery Center. Cấu trúc này khác tin 2026 nên cần đối chiếu trang chính thức trước khi dựa vào.","tips":["Kiểm tra lại tin tuyển chính thức trên careers.unilever.com / fanpage Unilever Careers Vietnam khi nộp đơn."],"basis":"reported","src":[5]}],"tests":[{"name":"Profile assessment (game-based)","provider":null,"format":"UFLP UK & Ireland 2026: 5 game ngắn online đo đặc điểm nhận thức, cảm xúc và xã hội; có phản hồi cá nhân. Một số nguồn cũ hơn và ở thị trường khác ghi khoảng 12 game. Tin tuyển Việt Nam 2026 chỉ gọi là 'Aptitude Test'. Nhà cung cấp hiện tại: Chưa có thông tin công khai đáng tin cậy.","basis":"official","src":[3,1]},{"name":"Lịch sử: game Pymetrics + video HireVue","provider":"Pymetrics, HireVue (theo báo chí năm 2017)","format":"Business Insider (2017) đưa tin Unilever bỏ CV ở vòng đầu, cho ứng viên chơi khoảng 12 game của Pymetrics rồi phỏng vấn video HireVue. Đây là thông tin lịch sử, không xác nhận cho UFLP Việt Nam hiện nay.","basis":"reported","src":[7]},{"name":"Digital Interview","provider":null,"format":"Video quay sẵn, câu hỏi cài sẵn; với một số stream có business case. Ứng viên báo cáo có giới hạn thời gian mỗi câu và chỉ được quay một lần.","basis":"official","src":[3,4,8]}],"values":{"name":"Unilever Standards of Leadership","items":["Chưa có thông tin công khai đáng tin cậy về danh sách đầy đủ hiện hành; TargetJobs khuyên ứng viên UFLP đọc về leadership standards của Unilever trước Digital Interview, nên hãy tìm bản mới nhất trên trang chính thức của Unilever."],"basis":"general","src":[4]},"prep":["Ngay bây giờ (tháng 11/2026): kiểm tra xem UFLP 2027 còn mở đơn không (bài đăng LinkedIn ghi hạn 30/11/2026) và chọn đúng một function.","Study guide: đọc phần game-based assessment để hiểu game đo traits, không phải kiến thức; làm bài khi tỉnh táo, liền một lần.","Mental math gym 10 phút/ngày để tăng tốc độ tính nhẩm và phản xạ, hỗ trợ cả game lẫn phần số liệu ở Discovery Centre.","Luyện chủ đề Logical và DI (biểu đồ doanh số, thị phần FMCG) vì Discovery Centre và business case dùng nhiều số liệu.","Luyện chủ đề SJT để làm quen tư duy ra quyết định trong tình huống công việc.","Viết 5–6 câu chuyện STAR bằng tiếng Anh và tập quay video 1–2 phút/câu như Digital Interview.","Làm Mock test 'Unilever-style' có bấm giờ, không quay lại câu trước, để quen áp lực thời gian.","Đọc về các brand Unilever ở Việt Nam và chuẩn bị ý tưởng cho group case."],"mock":{"title":"Unilever-style practice test","topics":{"Quant":4,"Logical":6,"Verbal":2,"DI":4,"SJT":4},"minutes":20,"navigation":false,"note":"Vòng 1 thật là 'Aptitude Test' dạng game (toàn cầu: 5 game đo nhận thức, cảm xúc, xã hội). App không mô phỏng được game phản xạ/trí nhớ hay phần đo đặc điểm cảm xúc–xã hội, chỉ luyện được nền tảng tư duy nhận thức (logic, tính nhẩm, đọc số liệu) và SJT. Tắt quay lại câu trước để giống game (không làm lại được lượt đã chơi). Digital Interview và Discovery Centre cần luyện riêng bằng video và case nhóm.","basis":"general","src":[1,3]},"pitfalls":["Nộp đơn qua trang tổng hợp hoặc nền tảng khác thay vì link chính thức: đơn không được xét (official).","Cố 'đoán đáp án đẹp' trong game đánh giá đặc điểm, dẫn đến hồ sơ thiếu nhất quán (general).","Lần đầu quay Digital Interview mà không tập trước: ứng viên báo cáo mỗi câu có giới hạn thời gian và chỉ được quay một lần (reported).","Trả lời chung chung 'Why Unilever' mà không nêu brand hay sáng kiến cụ thể ở Việt Nam (general).","Ở case nhóm Discovery Centre, nói nhiều nhưng không dựa trên số liệu, hoặc lấn át người khác (general)."],"sources":[{"title":"Unilever Future Leaders' Programme 2026 - Marketing (Ho Chi Minh City)","url":"https://careers.unilever.com/en/job/ho-chi-minh-city/unilever-future-leaders-programme-2026-marketing/34155/88566721056","publisher":"Unilever Careers","year":"2025","accessed":"2026-11-13"},{"title":"Unilever Future Leaders' Programme 2026 - Supply Chain (Manufacturing) (Ho Chi Minh City)","url":"https://careers.unilever.com/job/ho-chi-minh-city/unilever-future-leaders-programme-2026-supply-chain-manufacturing/34155/88566721008","publisher":"Unilever Careers","year":"2025","accessed":"2026-11-13"},{"title":"[Toàn Quốc] Unilever Future Leaders Programme 2026 - Chương trình tuyển dụng Quản trị viên tập sự","url":"https://ybox.vn/tuyen-dung/toan-quoc-unilever-future-leaders-programme-2026-chuong-trinh-tuyen-dung-quan-tri-vien-tap-su-tai-tap-doan-da-quoc-gia-unilever-marketing-customer-development-supply-chain-unilever-foods-solution-finance-human-resources-690de36fe48b1a70799fde9d","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"UK and Ireland Unilever Future Leaders Programme 2026","url":"https://careers.unilever.com/uk-and-ireland-unilever-future-leaders-programme-2026","publisher":"Unilever Careers","year":"2025","accessed":"2026-11-13"},{"title":"Applying to Unilever's Future Leaders Programme: the digital interview","url":"https://targetjobs.co.uk/employers/unilever/applying-to-unilevers-future-leaders-programme-the-digital-interview-453149","publisher":"TargetJobs","year":"2025","accessed":"2026-11-13"},{"title":"Bài đăng LinkedIn về UFLP 2027 (nhân viên Unilever chia sẻ)","url":"https://www.linkedin.com/in/hongphuongvo/","publisher":"LinkedIn (cá nhân)","year":"2026","accessed":"2026-11-13"},{"title":"Quản trị viên tập sự Unilever Future Leaders Programme (UFLP) - Unilever Việt Nam","url":"https://jobs.neu.edu.vn/jobs/quan-tri-vien-tap-su-unilever-future-leaders-programme-uflp-unilever-viet-nam-1202412191518","publisher":"Trung tâm Đổi mới sáng tạo và Hướng nghiệp ĐH Kinh tế Quốc dân","year":"2024","accessed":"2026-11-13"},{"title":"Consumer goods giant Unilever has been hiring employees using brain games and artificial intelligence","url":"https://www.businessinsider.in/consumer-goods-giant-unilever-has-been-hiring-employees-using-brain-games-and-artificial-intelligence-and-its-a-huge-success/articleshow/59356757.cms","publisher":"Business Insider","year":"2017","accessed":"2026-11-13"},{"title":"Unilever Interview review (candidate-reported)","url":"https://www.glassdoor.ca/Interview/Unilever-Interview-E3513-RVW8505941.htm","publisher":"Glassdoor","year":"n/a","accessed":"2026-11-13"}]},{"id":"heineken","name":"HEINEKEN Vietnam","program":"HEINEKEN Vietnam NextGen (Management Trainee Program)","industry":"FMCG (Bia & đồ uống)","lastChecked":"2026-11-13","summary":"NextGen là chương trình Management Trainee của HEINEKEN Vietnam cho sinh viên mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm. Mỗi năm công ty mở theo từng khối riêng (Supply Chain, Commerce/Sales & Marketing, Marketing) với lịch và vòng thi khác nhau. Điểm khác biệt: vòng đánh giá online từng có dạng gamified (game hoá), và vòng Assessment Centre (trước đây gọi là 'Brew Day') có case study nhóm hoặc cá nhân.","intake":{"text":"Mỗi khối mở theo lịch riêng. NextGen 2025 (Supply Chain): nộp đơn 14/02–30/03/2025, đi làm từ 06/2025. NextGen Commerce 2026 (Sales & Marketing): nộp đơn 05/05–16/06/2026. NextGen 2027 – Supply Chain: nộp đơn 12/10–20/11/2026 (đang mở tại ngày 13/11/2026 theo tin tuyển dụng), đi làm từ 03/2027.","basis":"official","src":[0,2,3,5]},"eligibility":[{"text":"Sinh viên mới tốt nghiệp hoặc có dưới 2 năm kinh nghiệm; bằng Cử nhân/Thạc sĩ ngành liên quan, GPA ≥ 7.0/10 (2.8/4.0) (NextGen 2027 – Supply Chain).","basis":"official","src":[5]},{"text":"Giao tiếp tiếng Anh tốt; sẵn sàng làm việc/luân chuyển tại các nhà máy bia HEINEKEN Việt Nam (khối Supply Chain, 2025 và 2027).","basis":"official","src":[0,5]},{"text":"Khối Commerce 2026: bằng Cử nhân Kinh doanh hoặc ngành liên quan, GPA ≥ 7.0/10; thành thạo tiếng Việt và tiếng Anh; sẵn sàng di chuyển toàn quốc (đặc biệt với Sales).","basis":"official","src":[2,4]}],"functions":[{"text":"Supply Chain: Technology & Brewing, Engineering & Packaging, Customer Service, Logistics & Planning (NextGen 2025).","basis":"official","src":[1]},{"text":"Commerce (Sales & Marketing) 2026: lộ trình 18 tháng, 3 giai đoạn 6 tháng luân chuyển Sales Representative, Sales Supervisor, Acting Area Sales Manager.","basis":"official","src":[2,4]},{"text":"Marketing Function (NextGen 2026) là một khối riêng với quy trình riêng.","basis":"official","src":[6]}],"stages":[{"name":"Online application","what":"Nộp đơn online qua form/trang tuyển dụng NextGen trong cửa sổ khoảng 6 tuần (2025: 14/02–30/03/2025; 2027 Supply Chain: 12/10–20/11/2026).","tips":["Chọn đúng khối (Supply Chain/Commerce/Marketing) vì mỗi khối có lịch và tiêu chí riêng.","Nộp sớm: ở khối 2027, vòng đánh giá online diễn ra song song trong thời gian nhận hồ sơ."],"basis":"official","src":[0,5]},{"name":"Online assessment (Gamified Online Assessment / Aptitude Test / Online competency assessment)","what":"2025 (Supply Chain): Gamified Online Assessment. 2026 (Marketing): Aptitude Test online. 2027 Supply Chain: 'Đánh giá năng lực trực tuyến' trong tháng 10–11/2026; tin tuyển dụng không mô tả chi tiết định dạng.","tips":["Luyện các bài reasoning ngắn có giới hạn thời gian để quen áp lực tốc độ.","Nếu là bài gamified: làm thử vài game dạng tương tự để quen giao diện, giữ tập trung, không đoán bừa."],"basis":"official","src":[0,5,6]},{"name":"Initial / Preliminary interview","what":"Phỏng vấn sơ bộ (2025: tháng 4; Commerce 2026: tháng 6; Supply Chain 2027: tháng 11/2026).","tips":["Chuẩn bị 3–4 câu chuyện theo STAR gắn với các giá trị của HEINEKEN.","Chuẩn bị lý do chọn khối và sẵn sàng làm việc ở nhà máy/tỉnh."],"basis":"official","src":[0,2,5]},{"name":"Assessment Centre (Brew Day / Comprehensive assessment)","what":"2025: Assessment Centre tháng 4/2025. 2026 (Marketing): Assessment Centre tháng 7, giải case study theo nhóm hoặc cá nhân. 2027 Supply Chain: 'Đánh giá toàn diện' tháng 12/2026. Các năm 2022–2023 vòng này được gọi là 'Brew Day'.","tips":["Luyện giải case kinh doanh/vận hành trong 30–60 phút và trình bày ngắn gọn.","Trong thảo luận nhóm: dẫn dắt có cấu trúc, lắng nghe, tổng kết; tránh lấn át người khác."],"basis":"official","src":[0,5,6,7]},{"name":"Final interview","what":"Phỏng vấn cuối (NextGen 2025: tháng 5/2025).","tips":["Ôn lại hiểu biết về thị trường bia Việt Nam và các thương hiệu của công ty.","Chuẩn bị câu hỏi cho lãnh đạo về lộ trình phát triển."],"basis":"official","src":[0]}],"tests":[{"name":"Gamified Online Assessment","provider":"TalentView (theo case study công khai của TalentView về HEINEKEN Vietnam; không rõ áp dụng năm nào)","format":"Các bài game hoá đo năng lực/hành vi; nguồn công khai không mô tả số phần hay thời gian.","basis":"official","src":[0,8]},{"name":"Aptitude Test (NextGen 2026 – Marketing)","provider":null,"format":"Bài aptitude online cho ứng viên qua vòng hồ sơ; không có mô tả chi tiết công khai.","basis":"official","src":[6]},{"name":"Online assessment của HEINEKEN Global Graduate Program (Supply Chain) – chương trình khác, chỉ để tham khảo","provider":null,"format":"Tình huống hành vi (situational behaviour scenarios, 'không cần chuẩn bị trước') kèm một bài cognitive test. Chưa xác nhận NextGen dùng cùng định dạng.","basis":"general","src":[9]}],"values":{"name":"HEINEKEN values (cấp tập đoàn)","items":["Passion for consumers and customers","Courage to dream and pioneer","Care for people and the planet","Enjoyment of life"],"basis":"official","src":[10,11]},"prep":["Xác định khối đang mở (tại 13/11/2026: NextGen 2027 – Supply Chain, hạn 20/11/2026) và nộp sớm vì vòng online chạy song song.","Study guide: đọc phần Logical và Situational Judgement để làm quen bài game/aptitude ngắn có giới hạn thời gian.","Mental math gym: 10 phút/ngày để tăng tốc tính nhẩm phần trăm, tỷ lệ, hữu ích cho cả test và case vận hành/sales.","Luyện chủ đề DI (đọc bảng/biểu đồ) vì case Supply Chain/Commerce thường dựa trên số liệu.","Làm Mock test 'HEINEKEN-style' 2–3 lần, xem lại câu sai theo từng chủ đề.","Chuẩn bị câu chuyện STAR gắn với 4 giá trị HEINEKEN, đặc biệt 'Courage to dream and pioneer'.","Luyện case nhóm 45 phút với bạn bè: phân vai, quản lý thời gian, trình bày 5 phút."],"mock":{"title":"HEINEKEN-style practice test","topics":{"Quant":4,"Logical":6,"Verbal":0,"DI":4,"SJT":6},"minutes":20,"navigation":true,"note":"Bài thật năm 2025 là Gamified Online Assessment; app không mô phỏng được game, chỉ luyện các năng lực nền (logic, số liệu, phán đoán tình huống) dưới áp lực thời gian. Tỷ trọng là ước lượng chung, không phải cấu trúc bài thật.","basis":"general","src":[0,8]},"pitfalls":["Nhầm khối/lịch: mỗi khối NextGen có thời gian và vòng khác nhau; xem đúng tin của khối mình ứng tuyển.","Nộp muộn trong khi vòng đánh giá online đã bắt đầu song song (lịch NextGen 2027 – Supply Chain).","Không sẵn sàng làm việc tại nhà máy/tỉnh dù đây là yêu cầu nêu rõ của khối Supply Chain.","Ở Assessment Centre: chỉ tập trung vào đáp án mà bỏ qua cách phối hợp nhóm (general)."],"sources":[{"title":"[Toàn Quốc] HEINEKEN Vietnam NextGen 2025 - Management Trainee Program","url":"https://vietnamworks.com/toan-quoc-heineken-vietnam-nextgen-2025-management-trainee-program-1869861-jv","publisher":"VietnamWorks","year":"2025","accessed":"2026-11-13"},{"title":"Heineken Việt Nam tuyển dụng Quản Trị Viên Tập Sự HEINEKEN Vietnam NextGen 2025 (Technology & Brewing, Engineering & Packaging, Customer Service, Logistics & Planning)","url":"https://ybox.vn/tuyen-dung/toan-quoc-heineken-viet-nam-tuyen-dung-chuong-trinh-quan-tri-vien-tap-su-heineken-vietnam-nextgen-2025-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-technology-and-brewing-engineering-and-packaging-customer-service-logistics-and-planning-67b2ee6ba12a102e71232d8c","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"Heineken Việt Nam - Chương Trình Quản Trị Viên Tập Sự NextGen Commerce 2026 (Sales & Marketing)","url":"https://ybox.vn/tuyen-dung/toan-quoc-heineken-viet-nam-chuong-trinh-quan-tri-vien-tap-su-nextgen-commerce-2026-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-sales-and-marketing-69f80755582ea202f2e83ba7","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"HEINEKEN Vietnam NextGen 2026","url":"https://hrc.com.vn/job/heineken-vietnam-nextgen-2026/","publisher":"HRC","year":"2026","accessed":"2026-11-13"},{"title":"HEINEKEN VIETNAM NEXTGEN COMMERCE 2026","url":"https://careerportal.vinuni.edu.vn/job/heineken-vietnam-nextgen-commerce-2026-14564","publisher":"VinUni Career Portal","year":"2026","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự NextGen 2027 - Supply Chain Tại Công Ty Bia Heineken Việt Nam","url":"https://ybox.vn/tuyen-dung/toan-quoc-chuong-trinh-quan-tri-vien-tap-su-nextgen-2027-supply-chain-tai-cong-ty-bia-heineken-viet-nam-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-6acd483e1a62196a64a068b0","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"HEINEKEN Vietnam NextGen 2026 (Marketing Function)","url":"https://bebee.com/vn/jobs/heineken-vietnam-nextgen-2026-marketing-function-heineken-vietnam-ho-chi-minh-city--theirstack-677593918","publisher":"beBee (tổng hợp tin tuyển dụng)","year":"2026","accessed":"2026-11-13"},{"title":"Chương Trình Tuyển Dụng Quản Trị Viên Tập Sự HEINEKEN Vietnam NextGen 2023","url":"https://enijobs.vn/heineken-vietnam-nextgen-2023/","publisher":"EniJobs","year":"2023","accessed":"2026-11-13"},{"title":"Heineken - TalentView (case study)","url":"https://www.talentview.com/heineken/","publisher":"TalentView","year":"không ghi","accessed":"2026-11-13"},{"title":"Global Graduate Program (Supply Chain) Job Details","url":"https://careers.theheinekencompany.com/Vietnam/job/Ho-Chi-Minh-City-Global-Graduate-Program-(Supply-Chain)/1243496301/","publisher":"HEINEKEN Careers","year":"không ghi","accessed":"2026-11-13"},{"title":"Sustainability Report 2022-2023","url":"https://heinekenbrasil.com.br/sustainability-report-2022-2023","publisher":"Grupo HEINEKEN Brasil","year":"2023","accessed":"2026-11-13"},{"title":"Brew a Better World","url":"https://www.heinekenmalaysia.com/brew-a-better-world/","publisher":"HEINEKEN Malaysia","year":"không ghi","accessed":"2026-11-13"}]},{"id":"suntory-pepsico","name":"Suntory PepsiCo Vietnam","program":"Suntory PepsiCo Management Trainee (MT)","industry":"FMCG (Nước giải khát)","lastChecked":"2026-11-13","summary":"Chương trình Management Trainee của Suntory PepsiCo Việt Nam dành cho sinh viên mới tốt nghiệp hoặc tối đa 2 năm kinh nghiệm, mục tiêu lên vị trí quản lý trong 3 năm. Quy trình gồm 4 vòng: Application, Testing (bài cognitive bằng tiếng Anh, chỉ làm 1 lần), Initial Interview và Career Camp & Final Interview. Career Camp có Business Case và Panel Interview, tiến hành bằng cả tiếng Việt và tiếng Anh.","intake":{"text":"Thường mở đơn cuối tháng 11 và đóng cuối tháng 12, nhận việc tháng 3–4 năm sau. MT2026: nộp đơn 25/11/2025–31/12/2025, onboard 03/2026. MT2025: đi làm từ 04/2025 (ứng viên nộp trước 30/11/2024 được làm thử bài aptitude). Chưa thấy thông báo MT2027 tại ngày 13/11/2026.","basis":"official","src":[0,1,2,3,4]},"eligibility":[{"text":"Sinh viên mới tốt nghiệp Cử nhân/Thạc sĩ (mọi ngành) hoặc tối đa 2 năm kinh nghiệm toàn thời gian; quốc tịch Việt Nam; GPA trên 7.0/10 hoặc tương đương; đi làm toàn thời gian từ 03/2026 (MT2026).","basis":"official","src":[0]},{"text":"Ứng viên đã vào vòng Assessment Center của MT hoặc Graduate Engineering/Sales Talent các năm trước không đủ điều kiện ứng tuyển lại (quy định năm 2021).","basis":"official","src":[5]}],"functions":[{"text":"MT2026: Sales, Marketing, Operations, Finance, People & Culture.","basis":"official","src":[2,4]},{"text":"MT2025: Marketing, Finance, People & Culture, Supply Chain & Logistics, Operations - Manufacturing, Sales.","basis":"official","src":[6]}],"stages":[{"name":"Application","what":"Nộp hồ sơ online trên careers.suntorypepsico.vn (MT2026: hạn 31/12/2025).","tips":["Nộp sớm: năm MT2025, người nộp trước 30/11/2024 được làm thử bài aptitude.","Chọn function phù hợp và nêu rõ lý do trong hồ sơ."],"basis":"official","src":[2,3]},{"name":"Testing","what":"Link bài test gửi qua email; chỉ được làm một lần và phải hoàn thành trước hạn. Bài cognitive test bằng tiếng Anh; trang tuyển dụng khuyên tìm bài mẫu để làm quen định dạng.","tips":["Làm bài ở nơi yên tĩnh, mạng ổn định vì chỉ có một lượt.","Luyện numerical, verbal và logical reasoning bằng tiếng Anh có bấm giờ."],"basis":"official","src":[1]},{"name":"Initial Interview","what":"Phỏng vấn sơ bộ; trang MT nêu phỏng vấn được thực hiện bằng cả tiếng Việt và tiếng Anh.","tips":["Chuẩn bị trả lời song ngữ: giới thiệu bản thân, động lực chọn function.","Dùng STAR, liên hệ với giá trị Yatte Minahare (dám thử, quyết tâm)."],"basis":"official","src":[0]},{"name":"Career Camp & Final Interview","what":"MT2026: Business Case và Panel Interview, bằng tiếng Việt và tiếng Anh. MT2025: ba hoạt động Games, Business Case và Panel Interview.","tips":["Luyện case FMCG (tăng trưởng doanh số, phân phối, ra mắt sản phẩm) và trình bày trước hội đồng.","Chuẩn bị ý kiến về ngành nước giải khát Việt Nam để dùng trong panel."],"basis":"official","src":[0,1]}],"tests":[{"name":"Cognitive test (Logical Reasoning, Numerical Reasoning, Verbal Reasoning)","provider":null,"format":"Ba phần logical, numerical và verbal reasoning bằng tiếng Anh; làm một lần qua link email trước hạn. Nguồn công khai không nêu thời lượng.","basis":"official","src":[1]},{"name":"Pre-employment testing (Talegent) cho các chương trình MT","provider":"Talegent (qua TalentView, theo case study công khai của TalentView; không rõ năm và không xác nhận cho chu kỳ hiện tại)","format":"Case study chỉ nêu dùng để sàng lọc ứng viên MT, không mô tả định dạng.","basis":"official","src":[7]},{"name":"Virtual test (EQ, toán, tiếng Anh)","provider":null,"format":"Theo chia sẻ ứng viên trên Glassdoor (khoảng 2022): bài test online gồm EQ, toán và tiếng Anh, sau đó là phỏng vấn sơ bộ, vòng assessment và phỏng vấn cuối với VP. Số lượng chia sẻ ít, đã cũ.","basis":"reported","src":[8]}],"values":{"name":"Core values của Suntory PepsiCo Việt Nam","items":["Growing for Good","Yatte Minahare","Giving Back to Society"],"basis":"official","src":[9]},"prep":["Theo dõi careers.suntorypepsico.vn từ giữa tháng 11: các chu kỳ gần đây mở cuối tháng 11, đóng 31/12.","Study guide: ôn numerical, verbal và logical reasoning bằng tiếng Anh, vì bài test chỉ làm được một lần.","Mental math gym hằng ngày để tăng tốc tính phần trăm, tỷ lệ, tăng trưởng.","Luyện chủ đề Verbal (True/False/Cannot Say) bằng tiếng Anh, và chủ đề DI (bảng, biểu đồ).","Làm Mock test 'Suntory PepsiCo-style' ít nhất 2 lần trước khi mở link bài thật.","Chuẩn bị phỏng vấn song ngữ Việt–Anh và câu chuyện STAR gắn với Yatte Minahare, Growing for Good, Giving Back to Society.","Luyện Business Case FMCG và trình bày trước panel cho vòng Career Camp."],"mock":{"title":"Suntory PepsiCo-style practice test","topics":{"Quant":6,"Logical":6,"Verbal":6,"DI":4,"SJT":0},"minutes":25,"navigation":true,"note":"Trang tuyển dụng nêu bài cognitive gồm Logical, Numerical và Verbal Reasoning bằng tiếng Anh, nên chia đều ba phần, thêm DI cho phần numerical dạng bảng/biểu đồ. Thời lượng và việc cho quay lại câu trước không được công bố nên đây là ước lượng.","basis":"official","src":[1]},"pitfalls":["Mở link test khi chưa sẵn sàng: bài chỉ làm được một lần.","Chủ quan với phần tiếng Anh: bài test và một phần phỏng vấn/Career Camp bằng tiếng Anh.","Ứng tuyển lại khi đã từng vào vòng Assessment Center năm trước (bị loại theo quy định năm 2021).","Nhầm với chương trình Graduate Engineering Talent (yêu cầu GPA và lịch khác) khi đọc tin."],"sources":[{"title":"Suntory PepsiCo - Management Trainee (MT2026)","url":"https://careers.suntorypepsico.vn/intro?id=171&meta_title=MT2026","publisher":"Suntory PepsiCo Vietnam","year":"2025","accessed":"2026-11-13"},{"title":"Suntory PepsiCo - Management Trainee (MT2025)","url":"https://careers.suntorypepsico.vn/intro?id=168&meta_title=%27MT2025%27","publisher":"Suntory PepsiCo Vietnam","year":"2024","accessed":"2026-11-13"},{"title":"[HCM/HN] Suntory PepsiCo Management Trainee 2026","url":"https://vieclam.tuoitre.vn/en/search-job/hcm-hn-suntory-pepsico-management-trainee-2026.35C629E7.html","publisher":"Việc làm Tuổi Trẻ / CareerViet","year":"2025","accessed":"2026-11-13"},{"title":"Suntory PepsiCo Vietnam Management Trainee 2025 Program","url":"https://cecs.tdtu.edu.vn/en/news/2024/suntory-pepsico-vietnam-management-trainee-2025-program","publisher":"Đại học Tôn Đức Thắng","year":"2024","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự Suntory PepsiCo Management Trainee","url":"https://enijobs.vn/chuong-trinh-quan-tri-vien-tap-su-suntory-pepsico-management-trainee/","publisher":"EniJobs","year":"2025","accessed":"2026-11-13"},{"title":"Why Suntory PepsiCo Vietnam Management Trainee Program 2021?","url":"https://vieclam.ctu.edu.vn/index.php/kinh-te-luat/1106-toan-quoc-chuong-trinh-tuyen-dung-quan-tri-vien-tap-su-cua-cong-ty-nuoc-giai-khat-hang-dau-viet-nam-suntory-pepsico-management-trainee-2021","publisher":"Đại học Cần Thơ","year":"2020","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự Suntory PepsiCo Management Trainee 2025","url":"https://ybox.vn/tuyen-dung/hcm-hn-chuong-trinh-quan-tri-vien-tap-su-tai-tap-doan-da-quoc-gia-suntory-pepsico-management-trainee-2025-marketing-finance-people-and-culture-supply-chain-and-logistics-operations-manufacturing-sales-673d3e63925c5d71f62f8036?sortId=PEPSICO-MT2025","publisher":"YBOX","year":"2024","accessed":"2026-11-13"},{"title":"Suntory Pepsi - TalentView (case study)","url":"https://www.talentview.com/suntory-pepsi/","publisher":"TalentView","year":"không ghi","accessed":"2026-11-13"},{"title":"Suntory PepsiCo Vietnam Beverage Management Trainee Interview Experience & Questions","url":"https://www.glassdoor.com/Interview/Suntory-PepsiCo-Vietnam-Beverage-Management-Trainee-Interview-Questions-EI_IE809796.0,32_KO33,51.htm","publisher":"Glassdoor (chia sẻ ứng viên)","year":"2022","accessed":"2026-11-13"},{"title":"About us","url":"https://www.suntorypepsico.vn/en/about-us","publisher":"Suntory PepsiCo Vietnam","year":"không ghi","accessed":"2026-11-13"}]},{"id":"frieslandcampina","name":"FrieslandCampina Vietnam (Dutch Lady)","program":"FCV Management Trainee Program (FCV MTP) / FrieslandCampina Global Traineeship","industry":"FMCG (Sữa & dinh dưỡng)","lastChecked":"2026-11-13","summary":"FCV MTP từng là chương trình tuyển dụng sinh viên mới tốt nghiệp lớn nhất hằng năm của FrieslandCampina Việt Nam, với 4 vòng: Application, Aptitude test, Initial interview, Business Challenge kèm Final interview. Chu kỳ FCV MTP tại Việt Nam gần nhất tìm được là 2023. Hiện tập đoàn tuyển qua Global Traineeship (có vị trí Global Traineeship Commerce – Vietnam), luân chuyển nhiều vai trò và có thể làm việc ở nhiều nước châu Á.","intake":{"text":"FCV MTP 2023: hạn nộp 20/01/2023, đi làm từ 04/2023. Global Traineeship chu kỳ 2026: mở 01/09–04/10/2026, khoá mới bắt đầu 01/03/2027. Không tìm thấy thông báo FCV MTP riêng cho Việt Nam năm 2024–2026.","basis":"official","src":[0,1,2]},"eligibility":[{"text":"FCV MTP 2023: sinh viên năm cuối Cử nhân/Thạc sĩ hoặc dưới 2 năm kinh nghiệm; giao tiếp tiếng Anh tốt; GPA ≥ 7.0/10 hoặc tương đương; đi làm toàn thời gian từ 04/2023.","basis":"official","src":[1,3]},{"text":"Global Traineeship Commerce – Vietnam: tối thiểu đã có bằng Cử nhân, tư duy toàn cầu; câu hỏi sàng lọc nhắc tốt nghiệp trước 09/2025 và 0–1 năm kinh nghiệm.","basis":"official","src":[4]},{"text":"Global Traineeship (chu kỳ 2026): tối thiểu bằng Cử nhân, không cần kinh nghiệm, dành cho sinh viên mới tốt nghiệp.","basis":"official","src":[2]}],"functions":[{"text":"FCV MTP 2023: Marketing, Sales, HR, Finance; lần đầu thêm Procurement Management Trainee.","basis":"official","src":[0,1]},{"text":"Global Traineeship Commerce – Vietnam: luân chuyển vai trò, có thể được bố trí tại Indonesia, Việt Nam, Trung Quốc, Hồng Kông, Philippines hoặc Malaysia; 'fast track to leadership with two challenging roles'.","basis":"official","src":[4]}],"stages":[{"name":"Application form","what":"Nộp đơn online (FCV MTP 2023: hạn 20/01/2023).","tips":["Kiểm tra trên careers.frieslandcampina.com xem chu kỳ hiện tại là FCV MTP hay Global Traineeship.","Làm rõ function mong muốn và mức sẵn sàng làm việc ở nước ngoài (với Global Traineeship)."],"basis":"official","src":[1,3]},{"name":"Aptitude test","what":"Bài aptitude online; nguồn công khai không mô tả nội dung, định dạng hay nhà cung cấp cho chu kỳ 2023.","tips":["Luyện numerical, verbal, logical reasoning bằng tiếng Anh có bấm giờ (general)."],"basis":"official","src":[1,3]},{"name":"Initial interview","what":"Phỏng vấn sơ bộ (vòng 3 của FCV MTP 2023).","tips":["Chuẩn bị câu chuyện STAR; tìm hiểu ngành sữa và thương hiệu Dutch Lady/Cô Gái Hà Lan."],"basis":"official","src":[3]},{"name":"Business Challenge & Final interview","what":"Vòng 4 năm 2023: Business Challenge rồi Final interview. Bản 2017 mô tả: ứng viên làm nhóm 6–8 người giải một thử thách kinh doanh thực tế của FCV, có 1 tuần đi thực địa rồi trình bày đề xuất; ai thể hiện tốt được phỏng vấn cuối với Leadership Team ngay trong ngày và có quyết định tại chỗ (định dạng 2023 có thể khác).","tips":["Luyện nghiên cứu thực địa nhanh (khảo sát điểm bán, phỏng vấn người tiêu dùng) và tổng hợp thành đề xuất.","Phân công rõ trong nhóm và tập trình bày trước hội đồng."],"basis":"official","src":[1,5]}],"tests":[{"name":"Aptitude test","provider":null,"format":"Chưa có thông tin công khai đáng tin cậy về số phần, thời gian hay nhà cung cấp.","basis":"official","src":[1,3]}],"values":{"name":"Chưa có thông tin công khai đáng tin cậy","items":[],"basis":"official","src":[]},"prep":["Kiểm tra careers.frieslandcampina.com/vnm để biết chu kỳ đang mở; Global Traineeship 2026 đã đóng ngày 04/10/2026.","Study guide: ôn tổng quát numerical, verbal, logical reasoning vì định dạng aptitude test chưa được công bố.","Mental math gym để xử lý nhanh số liệu doanh số và thị phần trong Business Challenge.","Luyện chủ đề DI (bảng/biểu đồ thị trường) và Verbal tiếng Anh.","Làm Mock test 'FrieslandCampina-style' để kiểm tra nền tảng tổng quát.","Tìm hiểu ngành sữa Việt Nam và danh mục Dutch Lady để chuẩn bị cho Business Challenge và phỏng vấn.","Luyện case nhóm có yếu tố thực địa: đặt giả thuyết, thu thập dữ liệu, trình bày đề xuất."],"mock":{"title":"FrieslandCampina-style practice test","topics":{"Quant":5,"Logical":5,"Verbal":5,"DI":5,"SJT":0},"minutes":20,"navigation":true,"note":"Nguồn chỉ nêu có 'Aptitude test' mà không mô tả định dạng, nên chia đều bốn nhóm năng lực aptitude phổ biến. Đây là cấu hình chung, không dựa trên bài thật.","basis":"general","src":[1,3]},"pitfalls":["Dựa vào thông tin FCV MTP cũ (2021–2023) trong khi chu kỳ hiện tại có thể là Global Traineeship với điều kiện và lịch khác.","Bỏ lỡ cửa sổ nộp đơn ngắn (Global Traineeship 2026: khoảng 5 tuần, 01/09–04/10).","Ở Business Challenge: chỉ phân tích trên bàn giấy mà không dùng dữ liệu thực địa (bản 2017 cho 1 tuần đi thực địa)."],"sources":[{"title":"Friesland Campina Việt Nam: Tuyển vị trí Quản Trị Viên Tập Sự (FCV MTP 2023)","url":"https://www.brandsvietnam.com/congdong/topic/329829-hcm-friesland-campina-viet-nam-tuyen-vi-tri-quan-tri-vien-tap-su","publisher":"Brands Vietnam","year":"2022","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự Management Trainee 2023 Do Tập Đoàn FrieslandCampina Vietnam Tổ Chức","url":"https://ivolunteervietnam.com/chuong-trinh-quan-tri-vien-tap-su-management-trainee-2023-do-tap-doan-frieslandcampina-vietnam-to-chuc.html","publisher":"iVolunteer Vietnam","year":"2022","accessed":"2026-11-13"},{"title":"Global Traineeship at FrieslandCampina","url":"https://careers.frieslandcampina.com/vnm/en/page/global-traineeship-frieslandcampina","publisher":"FrieslandCampina","year":"2026","accessed":"2026-11-13"},{"title":"FrieslandCampina Vietnam - Management Trainee Program 2023 (FCV MTP 2023)","url":"https://enijobs.vn/frieslandcampina-vietnam-management-trainee-program-2023-fcv-mtp-2023/","publisher":"EniJobs","year":"2022","accessed":"2026-11-13"},{"title":"Global Traineeship Commerce - Vietnam","url":"https://careers.frieslandcampina.com/mys/en/vacancy/56927","publisher":"FrieslandCampina","year":"2025","accessed":"2026-11-13"},{"title":"FrieslandCampina Viet Nam Management Trainee Program (FCV-MT)","url":"https://vieclam.ou.edu.vn/ban-tin/frieslandcampina-viet-nam-management-trainee-program-fcv-mt-.35a52783/vi","publisher":"Đại học Mở TP.HCM","year":"2017","accessed":"2026-11-13"}]},{"id":"nestle","name":"Nestlé Vietnam","program":"Nestlé #SparkTheNext Leaders Program (NSLP) - Management Trainee","industry":"FMCG / Food & Beverage","lastChecked":"2026-11-13","summary":"NSLP là chương trình Management Trainee 18 tháng của Nestlé Việt Nam, gồm 2 giai đoạn (12 tháng đầu luân chuyển đa chức năng), dành cho sinh viên năm cuối hoặc mới tốt nghiệp có dưới 1 năm kinh nghiệm. Quy trình 4 vòng: Online Application & Assessment → Initial Interview → Nestlé Camp/Sales Challenge (assessment centre) → Final Interview với hội đồng lãnh đạo. Nesternship (thực tập) là đường tắt vào NSLP.","intake":{"text":"NSLP 2026: Online Assessment 10/11–15/12/2025, Initial Interview tháng 1/2026, Nest Camp và Final Interview tháng 3–4/2026, bắt đầu tháng 5/2026 (official). NSLP 2025: hạn cuối tháng 12/2024, bắt đầu tháng 5/2025. Cổng việc làm Nestlé đang đăng tin Nestlé Vietnam Management Trainee bắt đầu tháng 5/2027; hạn nộp đợt này: Chưa có thông tin công khai đáng tin cậy (theo mô hình các năm trước thì mở khoảng tháng 11–12).","basis":"official","src":[1,3,2]},"eligibility":[{"text":"Sinh viên năm cuối hoặc mới tốt nghiệp, dưới 1 năm kinh nghiệm toàn thời gian.","basis":"official","src":[1,2]},{"text":"GPA tối thiểu 2.8/4 hoặc tương đương 7/10.","basis":"official","src":[1,2]},{"text":"Đi làm toàn thời gian được từ tháng 5 của năm nhập học (tháng 5/2026 cho đợt 2026, tháng 5/2027 cho đợt 2027); tiếng Anh tốt.","basis":"official","src":[1,2,9]},{"text":"Sinh viên còn đang học có thể đi đường Nesternship (thực tập): Nestlé Việt Nam gọi đây là đường tắt (fast-track) vào NSLP.","basis":"official","src":[6]}],"functions":[{"text":"NSLP 2025 tuyển: Sales, Commercial, Finance & Control, Supply Chain, Production, Engineering, Quality Assurance.","basis":"official","src":[3]},{"text":"Đợt 2026 được đăng là 10 phòng ban (trang tuyển dụng tổng hợp), với các tin như Commercial (Marketing), Supply Chain, Consumer Market Intelligence, Factory HR, Finance & Control, Production; nơi làm việc gồm TP.HCM, các nhà máy miền Nam (Đồng Nai) và nhà máy Bông Sen (Hưng Yên).","basis":"reported","src":[8,9]},{"text":"Cấu trúc chương trình: 18 tháng, 2 giai đoạn, 12 tháng đầu luân chuyển đa chức năng (cross-function rotation).","basis":"official","src":[0]}],"stages":[{"name":"Online Application & Assessment (Round 1)","what":"Nộp đơn qua cổng online và làm bài đánh giá trực tuyến. Tin NSLP 2023 trên nền tảng Pulsifi mô tả: Numerical reasoning (15 phút), Logical reasoning (10 phút), 3 bài đánh giá tính cách (25 phút) và video interview ngắn 3 câu (5 phút). Định dạng các năm sau có thể khác.","tips":["Luyện Quant (tỉ lệ, phần trăm, đọc bảng) với áp lực khoảng 1 phút/câu.","Luyện Logical (quy luật hình, chuỗi) có bấm giờ ngắn.","Bài tính cách: trả lời trung thực, nhất quán.","Tập trả lời video ngắn: ứng viên báo cáo thời gian chuẩn bị ngắn."],"basis":"official","src":[4,1,7]},{"name":"Initial Interview (Round 2)","what":"Phỏng vấn vòng đầu (đợt 2026: tháng 1/2026). Nội dung chi tiết: Chưa có thông tin công khai đáng tin cậy.","tips":["Chuẩn bị phần giới thiệu bản thân 1–2 phút bằng tiếng Anh, gắn với function ứng tuyển.","Chuẩn bị câu chuyện STAR thể hiện tôn trọng, hợp tác, chủ động."],"basis":"official","src":[1,2]},{"name":"Nestlé Camp / Sales Challenge – Assessment Center (Round 3)","what":"Assessment centre: theo tin trên cổng Nestlé, ứng viên giải các vấn đề kinh doanh thực tế và tương tác với lãnh đạo; một tin tuyển Marketing trainee ghi thời lượng 2 ngày. Đợt 2026: tháng 3–4/2026.","tips":["Luyện case nhóm FMCG (kênh phân phối, giá, khuyến mãi, chuỗi cung ứng) có trình bày số liệu.","Thể hiện vai trò trong nhóm: cấu trúc vấn đề, quản lý thời gian, tổng hợp ý.","Với Sales Challenge: ôn tính toán doanh số, biên lợi nhuận, mục tiêu theo kênh."],"basis":"official","src":[2,1]},{"name":"Final Interview (Round 4)","what":"Phỏng vấn cuối với hội đồng lãnh đạo kinh doanh (business leaders panel); đợt 2026: tháng 3–4/2026, offer và bắt đầu tháng 5/2026.","tips":["Chuẩn bị 'Why Nestlé / Why function' gắn với purpose và brand Nestlé tại Việt Nam.","Chuẩn bị kế hoạch phát triển 18 tháng của bản thân trong NSLP."],"basis":"official","src":[1,2]}],"tests":[{"name":"Numerical reasoning","provider":"Pulsifi (nền tảng đăng tin và đánh giá NSLP 2023)","format":"15 phút (NSLP 2023).","basis":"official","src":[4]},{"name":"Logical reasoning","provider":"Pulsifi","format":"10 phút (NSLP 2023).","basis":"official","src":[4]},{"name":"Personality assessments","provider":"Pulsifi","format":"3 bài đánh giá tính cách, tổng 25 phút (NSLP 2023).","basis":"official","src":[4]},{"name":"Short video interview","provider":"Pulsifi","format":"3 câu hỏi, khoảng 5 phút (NSLP 2023). Ứng viên ở Việt Nam báo cáo thời gian chuẩn bị mỗi câu ngắn (reported).","basis":"official","src":[4,7]}],"values":{"name":"Nestlé values – rooted in respect","items":["Respect for ourselves","Respect for others","Respect for diversity","Respect for the future"],"basis":"official","src":[5]},"prep":["Ngay bây giờ (tháng 11/2026): kiểm tra cổng việc làm Nestlé và nestle.com.vn cho NSLP đợt bắt đầu tháng 5/2027; các năm trước Online Assessment mở từ tháng 11 đến giữa tháng 12.","Study guide: đọc phần numerical/logical reasoning và bài tính cách để hiểu định dạng bài kiểu Pulsifi.","Mental math gym hằng ngày: bài numerical khoảng 15 phút cần tính phần trăm, tỉ lệ nhanh.","Luyện chủ đề Quant và Logical có bấm giờ; thêm DI với bảng số liệu bán hàng FMCG.","Làm Mock test 'Nestlé-style' 25 phút để quen nhịp làm bài.","Tập video interview 3 câu bằng tiếng Anh với thời gian chuẩn bị ngắn.","Chuẩn bị case nhóm và Sales Challenge cho Nestlé Camp; ôn 4 giá trị 'rooted in respect' để dùng trong phỏng vấn.","Cân nhắc Nesternship nếu còn đang học: Nestlé gọi đây là đường tắt vào NSLP."],"mock":{"title":"Nestlé-style practice test","topics":{"Quant":8,"Logical":6,"Verbal":2,"DI":4,"SJT":4},"minutes":25,"navigation":true,"note":"Dựa trên mô tả NSLP 2023 (numerical 15 phút, logical 10 phút, 3 bài tính cách, video 3 câu): trọng tâm Quant/DI và Logical, thêm ít SJT để luyện tư duy tình huống thay cho phần tính cách (app không chấm được bài tính cách). Phần video interview cần luyện riêng. Chưa có nguồn về việc có quay lại câu trước được hay không nên để bật điều hướng. Định dạng đợt 2027 có thể khác.","basis":"official","src":[4]},"pitfalls":["Bỏ lỡ hạn Online Assessment giữa tháng 12 vì tưởng đơn mở đến Tết (official: hạn 15/12/2025 ở đợt 2026).","Chủ quan bài numerical: ứng viên báo cáo bài không khó nhưng thời gian rất ngắn (reported).","Không tập trước video interview có thời gian chuẩn bị ngắn (reported).","Ở Nestlé Camp chỉ tập trung ý tưởng mà bỏ qua tính khả thi và số liệu (general).","Không đáp ứng GPA 2.8/4 (7/10) hoặc không thể đi làm từ tháng 5 (official)."],"sources":[{"title":"Nestlé #SparkTheNext Leaders Program","url":"https://www.nestle.com.vn/jobs/nestle-needs-youth/nestle-spark-the-next-program","publisher":"Nestlé Việt Nam","year":"2025","accessed":"2026-11-13"},{"title":"Nestlé #SparkTheNext Leaders Program 2026 - timeline & eligibility","url":"https://www.nestle.com.vn/en/node/431841","publisher":"Nestlé Việt Nam","year":"2025","accessed":"2026-11-13"},{"title":"Nestlé Vietnam Management Trainee - Job Details","url":"https://jobdetails.nestle.com/job/Ho-Chi-Minh-Nestl%C3%A9-Vietnam-Management-Trainee-70000/1456413233/","publisher":"Nestlé Jobs","year":"2026","accessed":"2026-11-13"},{"title":"[HCM/Đồng Nai] Nestlé #SparkTheNext Leaders 2025 - Management Trainee Program","url":"https://ybox.vn/tuyen-dung/hcm-dong-nai-chuong-trinh-tuyen-quan-tri-vien-tap-su-nestle-sparkthenext-leaders-2025-management-trainee-program-cua-tap-doan-da-quoc-gia-nestle-67373edc3a0dc87edea64ef5","publisher":"YBOX","year":"2024","accessed":"2026-11-13"},{"title":"Nestlé #SparkTheNext Leaders Program (NSLP) 2023","url":"https://job.pulsifi.me/companies/nestle-vn/33360107-3516-4883-801e-8bf9538d09e5/nestle-sparkthenext-leaders-program-nlsp-2023","publisher":"Pulsifi (cổng tuyển dụng Nestlé Việt Nam)","year":"2022","accessed":"2026-11-13"},{"title":"Our purpose and values","url":"https://www.nestle.in/about-us/our-purpose","publisher":"Nestlé India","year":"2025","accessed":"2026-11-13"},{"title":"What is Nesternship?","url":"https://www.nestle.com.vn/vi/what-nesternship","publisher":"Nestlé Việt Nam","year":"2026","accessed":"2026-11-13"},{"title":"Nestlé Interview Questions in Vietnam (candidate-reported)","url":"https://www.glassdoor.com/Interview/Nestl%C3%A9-Vietnam-Interview-Questions-EI_IE3492.0,6_IL.7,14_IN251.htm","publisher":"Glassdoor","year":"n/a","accessed":"2026-11-13"},{"title":"Management Trainee của nhà Nestlé đã chính thức mở đơn 10 phòng ban (hạn 15/12/2025)","url":"https://www.threads.com/@cake.vietnam_career/post/DQ-2l_bE9ak/management-trainee-c%E1%BB%A7a-nh%C3%A0-nestl%C3%A9-%C4%91%C3%A3-ch%C3%ADnh-th%E1%BB%A9c-m%E1%BB%9F-%C4%91%C6%A1n-10-ph%C3%B2ng-banth%E1%BB%9Di-gian-app","publisher":"Cake Vietnam Career (Threads)","year":"2025","accessed":"2026-11-13"},{"title":"Nestlé #SparkTheNext Leaders Program - Management Trainee 2026","url":"https://www.vietnamworks.com/nestle-sparkthenext-leaders-program-management-trainee-2026-1979682-jv","publisher":"VietnamWorks","year":"2025","accessed":"2026-11-13"}]},{"id":"vinamilk","name":"Vinamilk (Công ty Cổ phần Sữa Việt Nam)","program":"Vinamilk Graduate Talent Program (GTP)","industry":"FMCG / Sữa","lastChecked":"2026-11-13","summary":"Graduate Talent Program là chương trình tài năng trẻ của Vinamilk (mùa 1 năm 2025, mùa 2 năm 2026), thay cho chương trình 'Quản trị viên tập sự' (Management Trainee) trước đây. Đây là lộ trình 12 tháng làm nhân viên chính thức tại Head Office TP.HCM theo từng vị trí cụ thể, không phải MT luân chuyển. Quy trình gọn: Application → Aptitude Test online → In-depth Interview online → Final Interview trực tiếp.","intake":{"text":"GTP 2026: mở đơn 27/06–26/07/2026; Aptitude Test tháng 7/2026, In-depth Interview tháng 8/2026, Final Interview tháng 9/2026, onboarding tháng 10/2026. GTP 2025: mở đơn 06/06–06/07/2025, onboarding 09/2025. Kỳ vọng mùa sau mở khoảng tháng 6–7 (suy ra từ 2 mùa, chưa được công bố).","basis":"official","src":[0,1,2,4]},"eligibility":[{"text":"Sinh viên năm cuối hoặc mới tốt nghiệp, dưới 2 năm kinh nghiệm toàn thời gian (GTP 2026).","basis":"official","src":[0,3]},{"text":"GPA tích lũy từ 7/10 trở lên (hoặc tương đương) (GTP 2025 và 2026).","basis":"official","src":[0,2]},{"text":"Có thể đi làm toàn thời gian từ tháng 10/2026 (mùa 2026; mùa 2025 là từ tháng 9/2025). Làm việc tại Head Office, TP.HCM.","basis":"official","src":[0,2]}],"functions":[{"text":"Tuyển theo vị trí cụ thể ở nhiều khối. Vinamilk xác nhận mảng Tech & Data có 5 vị trí trong mùa 2 (2026).","basis":"official","src":[4]},{"text":"Danh sách mảng được trang bên thứ ba liệt kê cho mùa 2026 (không thống nhất giữa các nguồn): Retail Chain, Supply Chain, E-commerce, Modern Trade, Tech & Product, Trade Marketing, Product Development, International Business, HR, Internal Control & Compliance, Marketing & Communication. Hãy kiểm tra JD trên trang chính thức.","basis":"reported","src":[8]}],"stages":[{"name":"Online application","what":"Nộp hồ sơ trực tuyến trên trang careers của Vinamilk (2026: 27/06–26/07). Ứng viên trên diễn đàn cho biết có vòng lọc CV trước khi nhận link Aptitude Test.","tips":["Chọn đúng 1–2 vị trí phù hợp với chuyên ngành và đọc kỹ JD từng vị trí, vì GTP tuyển theo vị trí chứ không luân chuyển.","Trong CV/đơn, kể ví dụ cụ thể thể hiện '4 chất Vinamilk' (đào sâu/táo bạo, quyết liệt, tự chủ, luôn cầu tiến).","Đảm bảo GPA ≥ 7/10 được ghi rõ."],"basis":"official","src":[0,6]},{"name":"Aptitude Test (online)","what":"Bài kiểm tra năng lực trực tuyến (2026: tháng 7). Vinamilk có đăng video '3 tips vượt qua Aptitude Test' trên kênh Life at Vinamilk. Nội dung chi tiết chính thức không hiển thị công khai; một bài viết bên thứ ba mô tả bài test kiểm tra tư duy logic và đọc hiểu dữ liệu. Ứng viên trên diễn đàn kể rằng điểm test được dùng để xếp thứ tự mời phỏng vấn.","tips":["Luyện Logical và DI (bảng, biểu đồ) có bấm giờ trong Mock test.","Dùng Mental math gym để tính % và tỷ lệ nhanh.","Xem video tips chính thức của Life at Vinamilk trước khi làm bài."],"basis":"official","src":[0,4,5,6]},{"name":"In-depth Interview (online)","what":"Phỏng vấn chuyên sâu trực tuyến (2026: tháng 8; 2025: tháng 7–8). Trang chính thức có mục hỏi đáp về khác biệt giữa hai vòng phỏng vấn nhưng nội dung chi tiết chưa được xác minh.","tips":["Chuẩn bị 4–5 câu chuyện theo STAR gắn với từng chất trong '4 chất Vinamilk'.","Tìm hiểu kỹ mảng kinh doanh/thị trường của vị trí ứng tuyển.","Kiểm tra trước thiết bị, mạng, ánh sáng cho phỏng vấn online."],"basis":"official","src":[0,2]},{"name":"Final Interview (TP.HCM)","what":"Phỏng vấn cuối trực tiếp tại TP.HCM (2026: tháng 9; 2025: tháng 8). Hình thức cụ thể (case, thuyết trình hay hội đồng): Chưa có thông tin công khai đáng tin cậy.","tips":["Chuẩn bị quan điểm cá nhân về một vấn đề/cơ hội của Vinamilk trong mảng bạn ứng tuyển.","Giữ câu trả lời nhất quán với các vòng trước."],"basis":"official","src":[0,2]}],"tests":[{"name":"Aptitude Test","provider":null,"format":"Trực tuyến. Nội dung chính thức chưa công bố công khai; bài viết bên thứ ba mô tả bài kiểm tra tư duy logic và đọc hiểu dữ liệu (có thể gồm tình huống, dãy số, đọc hiểu), khoảng 45–60 phút. Không xác minh được nhà cung cấp.","basis":"reported","src":[0,5]}],"values":{"name":"4 chất Vinamilk (tiêu chí ứng viên GTP)","items":["Táo bạo / đào sâu (bold)","Quyết liệt (assertive)","Tự chủ (independent)","Luôn cầu tiến (always striving for progress)"],"basis":"official","src":[2]},"prep":["Đọc Study guide phần Logical reasoning và Data Interpretation, sau đó luyện chủ đề DI (bảng/biểu đồ doanh thu, thị phần).","Luyện Mental math gym mỗi ngày 10 phút: %, tăng trưởng, tỷ lệ, vì DI đòi hỏi tính nhanh không cần máy tính phức tạp.","Làm 'Vinamilk-style practice test' trong Mock test ít nhất 3 lần có bấm giờ, ghi lại dạng câu sai.","Viết sẵn 4 câu chuyện STAR, mỗi câu chứng minh một chất trong '4 chất Vinamilk'.","Nghiên cứu JD của vị trí đã chọn và báo cáo thường niên/tin tức Vinamilk gần nhất để có ý kiến cho Final Interview.","Theo dõi kênh Life at Vinamilk (Threads/Facebook) từ tháng 5–6 để không lỡ thời điểm mở đơn."],"mock":{"title":"Vinamilk-style practice test","topics":{"Quant":4,"Logical":6,"Verbal":4,"DI":6,"SJT":0},"minutes":25,"navigation":true,"note":"Cấu hình nghiêng về Logical và DI dựa trên mô tả bên thứ ba (tư duy logic, đọc hiểu dữ liệu). Định dạng chính thức, số câu và việc có cho quay lại câu trước hay không chưa được công bố, nên đây chỉ là bài luyện mô phỏng chung.","basis":"reported","src":[5]},"pitfalls":["Nhầm GTP là chương trình MT luân chuyển: GTP tuyển vào vị trí cụ thể làm nhân viên chính thức 12 tháng (official).","Nộp sát hạn: cửa sổ mở đơn chỉ khoảng 1 tháng (06/06–06/07/2025; 27/06–26/07/2026) (official).","Coi nhẹ Aptitude Test: ứng viên trên diễn đàn kể điểm test ảnh hưởng thứ tự mời phỏng vấn (reported).","Dùng thông tin cũ của chương trình 'Quản trị viên tập sự' 2020 (5 vòng) để chuẩn bị cho GTP — quy trình đã khác (general)."],"sources":[{"title":"Vinamilk Graduate Talent Program 2026","url":"https://careers.vinamilk.com.vn/vi/graduatetalent-program","publisher":"Vinamilk","year":"2026","accessed":"2026-11-13"},{"title":"Vinamilk Graduate Talent Program 2025","url":"https://graduatetalent.vinamilk.com.vn/","publisher":"Vinamilk","year":"2025","accessed":"2026-11-13"},{"title":"[HCM] Vinamilk Graduate Talent Program - Chương Trình Tuyển Dụng Tài Năng Trẻ 2025","url":"https://ybox.vn/tuyen-dung/hcm-vinamilk-graduate-talent-program-chuong-trinh-tuyen-dung-tai-nang-tre-tai-cong-ty-sua-viet-nam-vinamilk-full-time-2025-6842f6b9e7b9c57a7a563ba7","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"[HCM] Vinamilk Graduate Talent Program 2026 - Chương Trình Tuyển Dụng Nhân Tài Trẻ 2026","url":"https://ybox.vn/tuyen-dung/hcm-vinamilk-graduate-talent-program-chuong-trinh-phat-trien-tai-nang-tre-tai-cong-ty-kinh-doanh-sua-viet-nam-vinamilk-full-time-2026-6a3fe28dc1ee587f48b135ea","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Life at Vinamilk: Graduate Talent Program mùa 2 mở 5 vị trí Tech & Data / 3 tips vượt qua Aptitude Test","url":"https://www.threads.com/@lifeatvinamilk/post/DaKHKMfjxhV/","publisher":"Life at Vinamilk (Threads, kênh chính thức)","year":"2026","accessed":"2026-11-13"},{"title":"Vinamilk Recruits Interns 2025: GTP Opportunity For Young Talents","url":"https://viecoi.vn/en/cam-nang-nghe-nghiep/chi-tiet-kham-pha-tung-vong-thi-tuyen-vao-vi-tri-management-trainee-quan-tri-vien-tap-su-tai-cong-ty-vinamilk-moi-nhat-nam-2020-915.html","publisher":"Viecoi.vn","year":"2025","accessed":"2026-11-13"},{"title":"Nhận email từ Vinamilk Graduate Talent Program (diễn đàn ứng viên)","url":"https://voz.vn/t/nhan-email-tu-vinamilk-graduate-talent-program.1121624/","publisher":"VOZ Forum","year":"2025","accessed":"2026-11-13"},{"title":"Vinamilk chính thức khởi động chương trình 'Quản trị viên tập sự 2020'","url":"https://vietnamfinance.vn/vinamilk-chinh-thuc-khoi-dong-chuong-trinh-quan-tri-vien-tap-su-2020-d53719.html","publisher":"VietnamFinance","year":"2020","accessed":"2026-11-13"},{"title":"Vinamilk Graduate Talent Program 2026 chính thức mở đơn (danh sách vị trí)","url":"https://www.threads.com/@tramvieclam/post/DaH-MGWE24n/","publisher":"Trạm Việc Làm (Threads, bên thứ ba)","year":"2026","accessed":"2026-11-13"}]},{"id":"techcombank","name":"Techcombank (Ngân hàng TMCP Kỹ Thương Việt Nam)","program":"Techcombank Future Gen (TFG)","industry":"Ngân hàng","lastChecked":"2026-11-13","summary":"Techcombank Future Gen là chương trình Quản trị viên tập sự (Management Trainee) thường niên, kéo dài 24 tháng, theo các stream Business, General Management, Technology, Digital, Data & AI. Tên chương trình gắn với năm onboarding (TFG 2027 tuyển năm 2026). Điểm khác biệt: có cả Aptitude Test và Functional Test theo stream, Remote Interview, Assessment Center rồi Panel Interview.","intake":{"text":"TFG 2027: nhận hồ sơ 24/07–30/09/2026; Remote Interview, Aptitude Test, Functional Test khoảng tháng 8–10; Assessment Center tháng 10; Panel Interview tháng 11; onboarding dự kiến tháng 1/2027. TFG 2026 (mùa 5): nhận hồ sơ 28/07–30/09/2025. TFG 2025 (mùa 4): mở từ 12/06/2024. Thường mở đơn tháng 6–7 và đóng 30/9.","basis":"official","src":[0,1,4,3]},"eligibility":[{"text":"Sinh viên năm cuối hoặc người trẻ dưới 2 năm kinh nghiệm làm việc.","basis":"official","src":[1,3]},{"text":"Làm việc toàn thời gian theo hợp đồng lao động và nộp bằng tốt nghiệp trước thời điểm onboarding (dự kiến tháng 1/2027 cho TFG 2027).","basis":"official","src":[0]}],"functions":[{"text":"TFG 2027: Công nghệ (Technology), Dữ liệu & AI, Kinh doanh (Business), Quản trị chung (General Management); một số nguồn liệt kê thêm Digital.","basis":"official","src":[1]},{"text":"TFG 2025: 4 nhóm Technology, Digital & Data, Business, General Management; thời lượng 24 tháng.","basis":"official","src":[3]}],"stages":[{"name":"Online application","what":"Nộp đơn trực tuyến trên trang tuyển dụng Techcombank (TFG 2027: 24/07–30/09/2026), chọn stream.","tips":["Chọn stream phù hợp nền tảng, vì Functional Test ra đề theo stream.","Thể hiện Ability, Aspiration và Commitment bằng thành tích định lượng."],"basis":"official","src":[0,1]},{"name":"Remote Interview","what":"Phỏng vấn từ xa (khoảng tháng 8–10). Với TFG 2025, một nguồn mô tả là 'phỏng vấn qua điện thoại và kiểm tra khả năng'. Hình thức chính xác (gọi điện hay video ghi hình): Chưa có thông tin công khai đáng tin cậy.","tips":["Chuẩn bị phần giới thiệu 60–90 giây và lý do chọn Techcombank/stream.","Có thể phỏng vấn bằng tiếng Anh — luyện trả lời song ngữ (general)."],"basis":"official","src":[0,2]},{"name":"Aptitude Test","what":"Bài test năng lực tư duy trực tuyến (khoảng tháng 8–10/2026). Định dạng chi tiết và nhà cung cấp chưa được công bố công khai.","tips":["Luyện đủ Quant, Logical, Verbal, DI có bấm giờ.","Luyện bài Verbal bằng tiếng Anh."],"basis":"official","src":[0]},{"name":"Functional Test","what":"Bài kiểm tra chuyên môn theo stream. Theo một đơn vị luyện thi (không chính thức): stream Data & AI có thể gồm trắc nghiệm và bài lập trình/xử lý dữ liệu; stream Business nên ôn quản trị doanh nghiệp, tài chính tiền tệ, ngân hàng thương mại.","tips":["Ôn kiến thức nền của stream (ngân hàng thương mại, tài chính, hoặc SQL/Python với Data & AI).","Đọc báo cáo thường niên Techcombank để nắm mô hình kinh doanh."],"basis":"reported","src":[0,5]},{"name":"Assessment Center","what":"Vòng Assessment Center (tháng 10). Có trong cả TFG 2025 và TFG 2027. Nội dung chi tiết (case nhóm, thuyết trình...): Chưa có thông tin công khai đáng tin cậy ở mức chính thức.","tips":["Luyện thảo luận case nhóm: lắng nghe, tổng hợp ý, quản lý thời gian.","Luyện thuyết trình ngắn có cấu trúc (vấn đề – phân tích – đề xuất)."],"basis":"official","src":[0,2]},{"name":"Panel Interview","what":"Phỏng vấn hội đồng (tháng 11/2026), sau đó đề xuất vị trí/offer và onboarding tháng 1/2027. TFG 2025 được mô tả có vòng phỏng vấn nhóm trước khi đề xuất vị trí.","tips":["Chuẩn bị tầm nhìn 2–3 năm của bản thân trong ngân hàng.","Có quan điểm về chiến lược số hóa/dữ liệu của Techcombank."],"basis":"official","src":[0,2]}],"tests":[{"name":"Aptitude Test","provider":null,"format":"Trực tuyến; số phần, thời gian và nhà cung cấp chưa được công bố công khai.","basis":"official","src":[0]},{"name":"Functional Test (theo stream)","provider":null,"format":"Kiến thức chuyên môn theo stream; với Data & AI có thể gồm trắc nghiệm và coding (theo đơn vị luyện thi, không chính thức).","basis":"reported","src":[0,5]}],"values":{"name":"Tiêu chí ứng viên TFG và giá trị cốt lõi","items":["Ability (năng lực)","Aspiration (khát vọng phát triển)","Commitment (cam kết)","Khách hàng là trọng tâm (giá trị cốt lõi, báo cáo thường niên 2022)","Đổi mới và Sáng tạo (giá trị cốt lõi, báo cáo thường niên 2022)","Định vị thương hiệu: 'Vượt trội hơn mỗi ngày'"],"basis":"official","src":[3,6,1]},"prep":["Học Study guide và luyện chủ đề Quant, Logical, Verbal, DI — ưu tiên phiên bản tiếng Anh.","Mental math gym hằng ngày để tính lãi suất, tăng trưởng, tỷ suất nhanh.","Làm 'Techcombank-style practice test' trong Mock test, mục tiêu hoàn thành đúng giờ.","Ôn kiến thức Functional theo stream (ngân hàng thương mại/tài chính cho Business; SQL/Python cho Data & AI).","Luyện case nhóm và thuyết trình 5 phút để chuẩn bị Assessment Center.","Chuẩn bị câu chuyện STAR chứng minh Ability – Aspiration – Commitment.","Đặt nhắc nhở tháng 6–7 để nộp đơn sớm, trước hạn 30/9."],"mock":{"title":"Techcombank-style practice test","topics":{"Quant":6,"Logical":6,"Verbal":6,"DI":6,"SJT":0},"minutes":30,"navigation":true,"note":"Techcombank xác nhận có Aptitude Test nhưng chưa công bố định dạng; cấu hình cân bằng 4 mảng là mô phỏng chung cho bài aptitude ngân hàng. Functional Test (chuyên môn, coding) và Assessment Center không mô phỏng được trong app.","basis":"general","src":[0]},"pitfalls":["Nhầm tên năm: 'TFG 2027' là đợt tuyển năm 2026 (onboarding 1/2027) (official).","Chỉ ôn aptitude mà bỏ qua Functional Test theo stream (official/reported).","Chờ đến tháng 9 mới nộp: các vòng Remote Interview/test bắt đầu từ tháng 8 (official).","Thiếu chuẩn bị tiếng Anh cho test và phỏng vấn (general)."],"sources":[{"title":"TECHCOMBANK FUTURE GEN 2027","url":"https://tuyendung.techcombankjobs.com/techcombank-future-gen","publisher":"Techcombank","year":"2026","accessed":"2026-11-13"},{"title":"Chương Trình Tuyển Dụng Quản Trị Viên Tập Sự 'Techcombank Future Gen 2027' (Công Nghệ, Dữ Liệu & AI, Kinh Doanh, Quản Trị Chung)","url":"https://ybox.vn/tuyen-dung/toan-quoc-chuong-trinh-tuyen-dung-quan-tri-vien-tap-su-techcombank-future-gen-2027-tai-ngan-hang-ky-thuong-viet-nam-techcombank-danh-cho-sinh-vien-nam-cuoi-hoac-duoi-2-nam-kinh-nghiem-cong-nghe-du-lieu-and-ai-kinh-doanh-quan-tri-chung-6a6c05edc4b4780eb131d97f","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Techcombank Future Gen 2025 Chính Thức Mở Đơn Đăng Ký","url":"https://ivolunteer.vn/techcombank-future-gen-2025-chinh-thuc-mo-don-dang-ky-s24878.html","publisher":"iVolunteer.vn","year":"2024","accessed":"2026-11-13"},{"title":"Techcombank Future Gen 2025: Chương trình Quản trị viên Tập sự mùa thứ 4 - đổi mới từ nguồn nhân lực trẻ tài năng","url":"https://baodautu.vn/techcombank-future-gen-2025-chuong-trinh-quan-tri-vien-tap-su-mua-thu-4---doi-moi-tu-nguon-nhan-luc-tre-tai-nang-d218605.html","publisher":"Báo Đầu tư","year":"2024","accessed":"2026-11-13"},{"title":"Cơ hội trở thành quản trị viên tập sự làm việc tại Techcombank","url":"https://tuoitre.vn/co-hoi-tro-thanh-quan-tri-vien-tap-su-lam-viec-tai-techcombank-20250815192630868.htm","publisher":"Tuổi Trẻ Online","year":"2025","accessed":"2026-11-13"},{"title":"Làm sao để chuẩn bị tốt cho vòng Functional Test Techcombank Future Gen 2027?","url":"https://www.threads.com/@casemate.aud/post/DfTZYBKk_yH/","publisher":"Casemate (Threads, đơn vị luyện thi)","year":"2026","accessed":"2026-11-13"},{"title":"Báo cáo thường niên Techcombank 2022","url":"https://techcombank.com/content/dam/techcombank/public-site/imported-assets/VIE-Book-TCB-AR-22-Web-23063f37a7.pdf","publisher":"Techcombank","year":"2023","accessed":"2026-11-13"}]},{"id":"vpbank","name":"VPBank (Ngân hàng TMCP Việt Nam Thịnh Vượng)","program":"VPBank Young Talents","industry":"Ngân hàng","lastChecked":"2026-11-13","summary":"VPBank Young Talents là chương trình tài năng trẻ/Management Trainee nhằm đưa sinh viên mới ra trường thành quản lý trẻ, với lộ trình đào tạo cá nhân hóa 15 tháng đầu và cam kết làm việc tối thiểu 3 năm (2025). Quy trình 4 vòng: sơ loại hồ sơ → kiểm tra năng lực online → phỏng vấn nhóm → phỏng vấn cá nhân với lãnh đạo. Có kênh tuyển thẳng qua Hackathon và học bổng Future VPBanker.","intake":{"text":"Young Talents 2026: thời gian tuyển chọn tháng 4–8/2026, xét nhiều đợt; sơ loại hồ sơ đến 05/06/2026 theo trang chính thức (một số trang trường ghi hạn 02/05/2026). Young Talents 2025: mở đơn từ tháng 5/2025, test online và phỏng vấn nhóm từ tháng 6/2025, phỏng vấn cá nhân từ tháng 7, gia nhập từ tháng 8/2025. Thường mở đơn tháng 3–5.","basis":"official","src":[0,1,7]},"eligibility":[{"text":"Sinh viên năm cuối, mới tốt nghiệp cử nhân/thạc sĩ, dưới 1 năm kinh nghiệm; làm việc tại Hà Nội và TP.HCM (2025–2026).","basis":"official","src":[2,3]},{"text":"Cam kết làm việc tối thiểu 03 năm tại VPBank (YT 2025).","basis":"reported","src":[3]},{"text":"Kênh ưu tiên: thí sinh đạt giải VPBank Technology Hackathon 2025 được tuyển thẳng vào Young Talents 2025; sinh viên nhận học bổng Future VPBanker 2025 được vào thẳng vòng phỏng vấn cuối của Young Talents 2026.","basis":"official","src":[4,5]}],"functions":[{"text":"Tuyển theo khối, ví dụ năm 2026: Nguồn vốn & Thị trường tài chính, KHDN lớn và đầu tư, Kiểm toán nội bộ, Tài chính, NHGD & Đầu tư trực tiếp nước ngoài; cùng các khối kinh doanh (mục tiêu trở thành ARM sau 8–15 tháng tùy đánh giá).","basis":"official","src":[6,2]}],"stages":[{"name":"Sơ loại hồ sơ (Online application)","what":"Nộp hồ sơ online qua mẫu thông tin ứng viên/trang tuyển dụng VPBank; chọn khối mong muốn.","tips":["Chọn khối phù hợp chuyên ngành và nêu rõ lý do.","Điền đầy đủ mẫu thông tin ứng viên, đính kèm CV cập nhật."],"basis":"official","src":[0,1]},{"name":"Kiểm tra năng lực (Online test)","what":"Bài kiểm tra trực tuyến (2025: từ tháng 6; 2026: từ tháng 5). Nội dung, thời lượng và nhà cung cấp chưa được VPBank công bố công khai.","tips":["Luyện bộ aptitude tổng hợp: Quant, Logical, Verbal, DI.","Làm bài ở nơi yên tĩnh, mạng ổn định."],"basis":"official","src":[0,1]},{"name":"Phỏng vấn nhóm (Group interview)","what":"Phỏng vấn/thảo luận nhóm (2025 và 2026: từ tháng 6). Hình thức chi tiết: Chưa có thông tin công khai đáng tin cậy.","tips":["Luyện vai trò tổng hợp ý và dẫn dắt nhóm mà không áp đảo.","Đưa ra kết luận có số liệu và đề xuất cụ thể."],"basis":"official","src":[0,1]},{"name":"Phỏng vấn cá nhân (Final interview)","what":"Phỏng vấn cá nhân do lãnh đạo VPBank thực hiện (2025: từ tháng 7), sau đó gia nhập từ tháng 8.","tips":["Tìm hiểu chiến lược và kết quả kinh doanh gần nhất của VPBank và khối ứng tuyển.","Chuẩn bị trả lời về cam kết gắn bó dài hạn."],"basis":"official","src":[1]}],"tests":[{"name":"Kiểm tra năng lực trực tuyến","provider":null,"format":"Chưa có thông tin công khai đáng tin cậy về số phần, thời gian và dạng câu hỏi; VPBank chỉ công bố đây là bài kiểm tra trực tuyến.","basis":"official","src":[1,0]}],"values":{"name":"Chưa có thông tin công khai đáng tin cậy","items":[],"basis":"official","src":[]},"prep":["Học Study guide phần aptitude tổng quát và luyện chủ đề Quant/Logical/Verbal/DI.","Mental math gym để tính lãi, tỷ lệ, tăng trưởng nhanh.","Làm 'VPBank-style practice test' trong Mock test 2–3 lần, có bấm giờ.","Luyện SJT để chuẩn bị tư duy tình huống cho phỏng vấn nhóm.","Tìm hiểu khối ứng tuyển (vd. ARM khối khách hàng doanh nghiệp) và các sản phẩm chính.","Theo dõi Hackathon và học bổng Future VPBanker nếu còn là sinh viên năm 3–4 — đây là kênh vào thẳng."],"mock":{"title":"VPBank-style practice test","topics":{"Quant":5,"Logical":5,"Verbal":4,"DI":4,"SJT":2},"minutes":25,"navigation":true,"note":"VPBank chưa công bố định dạng bài test online; cấu hình là mô phỏng chung cho bài aptitude ngân hàng, thêm vài câu SJT để chuẩn bị tư duy tình huống cho phỏng vấn nhóm.","basis":"general","src":[1]},"pitfalls":["Không để ý các đợt xét tuyển: 2026 tuyển nhiều đợt và hạn giữa các nguồn khác nhau — luôn lấy mốc trên trang chính thức (official).","Ứng tuyển khi đã quá 1 năm kinh nghiệm (official).","Không cân nhắc cam kết làm việc tối thiểu 3 năm trước khi nhận offer (reported)."],"sources":[{"title":"VPBank Young Talents 2026","url":"https://hr.vpbank.com.vn/ta/VPBankYoungTalents2026/index.html","publisher":"VPBank","year":"2026","accessed":"2026-11-13"},{"title":"VPBank Young Talents 2025","url":"https://tuyendung.vpbank.com.vn/landing/VPBankYoungTalents2025.html","publisher":"VPBank","year":"2025","accessed":"2026-11-13"},{"title":"VPBank Young Talents 2026 - Chi tiết công việc","url":"https://tuyendung.vpbank.com.vn/job/VPBank-Young-Talents-2026/3347-vi_VN/","publisher":"VPBank","year":"2026","accessed":"2026-11-13"},{"title":"Tuyển VPBank Young Talents 2025 - Chương Trình Tài Năng Trẻ VPBank","url":"https://www.topcv.vn/brand/vpbank/tuyen-dung/vpbank-young-talents-2025-chuong-trinh-tai-nang-tre-vpbank-j1731063.html","publisher":"TopCV","year":"2025","accessed":"2026-11-13"},{"title":"VPBank trao 54 học bổng Future VPBanker 2025 cho sinh viên xuất sắc","url":"https://tuoitre.vn/vpbank-trao-54-hoc-bong-future-vpbanker-2025-cho-sinh-vien-xuat-sac-20260106145619268.htm","publisher":"Tuổi Trẻ Online","year":"2026","accessed":"2026-11-13"},{"title":"VPBank Technology Hackathon 2025 trở lại với quy mô lớn","url":"https://thitruongtaichinhtiente.vn/vpbank-technology-hackathon-2025-tro-lai-voi-quy-mo-lon-67838.html","publisher":"Thị trường Tài chính Tiền tệ","year":"2025","accessed":"2026-11-13"},{"title":"Tuyển dụng VPBank: Young Talents Khối Nguồn vốn & Thị trường tài chính (18/05/2026)","url":"https://ub.com.vn/t/tuyen-dung-vpbank-young-talents-khoi-nguon-von-thi-truong-tai-chinh-18-05-2026/460224","publisher":"U&Bank","year":"2026","accessed":"2026-11-13"},{"title":"Chương trình tài năng trẻ VPBank Young Talent 2026","url":"https://soict.hust.edu.vn/chuong-trinh-tai-nang-tre-vpbank-young-talent-2026.html","publisher":"Trường CNTT&TT - ĐH Bách khoa Hà Nội","year":"2026","accessed":"2026-11-13"}]}];
